import"./NZTpNUN0.js";import"./BkvxQF8z.js";import{t,P as n,q as a}from"./D3cAVrQp.js";var o=t("<h1>Shared Capital and Social Inheritance Protocol v0.1.4</h1> <h2>Plural public ownership, collective capital custody, and broadly distributed capital claims</h2> <p><strong>Tier:</strong> 1 — Foundational Economic Protocol<br> <strong>Status:</strong> Internal architecture draft for adversarial review<br> <strong>Revision:</strong> 0.1.4 (2026-08-27)<br> <strong>Responsible:</strong> Global Governance Frameworks initiative<br> <strong>Constitutional interface:</strong> Constitutional Interface Specification <code>CIS/0.2.4</code><br> <strong>Lifecycle interface:</strong> current compatible Governance Method, Experiment, Adoption, and Implementation Authority Interface Specification (<code>GMEAIA</code>)<br> <strong>Authority effect:</strong> None until lawfully adopted by a competent jurisdiction, Indigenous authority, public compact, trust charter, treaty protocol, or other valid constituting instrument<br> <strong>Primary role:</strong> Governance architecture for plural shared-capital institutions and social-inheritance arrangements that broaden beneficial claims on productive wealth without creating a single public owner or converting material security into conditional capital participation</p> <h3>Related frameworks</h3> <ul><li><strong>Adaptive Tax Framework</strong> — lawful revenue architecture, inheritance and gift taxation, fiscal incidence, capital and wealth bases, and revenue transfers into shared-capital institutions</li> <li><strong>Aurora Accord v1.3.2</strong> — purpose limitation, identity-function separation, anti-linkage, and protected beneficiary-data governance</li> <li><strong>Adaptive Universal Basic Income (AUBI)</strong> — unconditional material-security floor and contribution-recognition architecture</li> <li><strong>Financial Systems Framework</strong> — Hearts, Leaves, Treasury, settlement, liquidity, financial observability, and financial-system safeguards</li> <li><strong>Nested Economies Framework</strong> — economic subsidiarity, cross-scale compacts, material exit, and protected non-convertibility</li> <li><strong>Work in Liberation Framework</strong> — worker rights, organized contribution, labour governance, and worker-ownership interfaces</li> <li><strong>Hearthstone Protocol</strong> — voluntary and separately lawful asset transition, stewardship trusts, rematriation, and cooperative conversion</li> <li><strong>Bioregional Polis</strong> — municipal land, Community Land Trusts, local anti-speculation policy, and community purchase mechanisms</li> <li><strong>Pathfinder / Regenerative Enterprise</strong> — enterprise-level profit sharing, ESOPs, Community Investment Trusts, steward ownership, and regenerative-capital practice</li> <li><strong>Sundown Protocol</strong> — just-transition investment-policy requests, divestment coordination, public-fund exclusions, and sovereign-wealth restructuring that require fund-level mandate or valid compact authority</li> <li><strong>Aegis Protocol</strong> — federated transition-finance facilities, public trusts, development banks, pension-backed vehicles, and civilian capability-conversion finance under separately constituted authority</li> <li><strong>Treaty for Our Only Home</strong> — public finance, Global Commons Fund, commons dividends, Treaty competence, rights, and constitutional limits</li> <li><strong>Integrated Meta-Governance</strong> — coordination among authorities without residual economic sovereignty</li> <li><strong>Indigenous Sovereignty and Planetary Healing</strong> — Indigenous authority, consent, protected knowledge, and non-interference</li> <li><strong>Justice and data-governance frameworks</strong> — adjudication, remedy, fiduciary accountability, privacy, cybersecurity, and data rights</li></ul> <h3>Source freeze</h3> <p>The following texts were read directly in preparing this draft. The table records provenance; it does not make every source an operative dependency.</p> <table><thead><tr><th>Instrument</th><th>SHA-256</th></tr></thead><tbody><tr><td>Adaptive Tax Framework v0.1.2</td><td><code>8d7c002650a1a3773f7a4f20b1fa2120c72bd11b825602de599b08a43ee53a2c</code></td></tr><tr><td>Constitutional Interface Specification v0.2.3</td><td><code>e6ec294bbce0994a0d2c609a95bd6a392e87abe34e8812fe0c5a958851810dc4</code></td></tr><tr><td>Treaty for Our Only Home v1.3</td><td><code>5fd9f5364657b21e9c51ec7b3a03842bc9bd5ff99597205ad1607451e2c9ff77</code></td></tr><tr><td>AUBI v2.5</td><td><code>c099938d9310fc0e286fa710ad59532178873fe79d7cdaf9acc130c7360d4db4</code></td></tr><tr><td>Financial Systems v3.4</td><td><code>0c088d4c9cfc501ccc1b3fb5efab579d295460e68b0ddddd37ef2d036c175ba5</code></td></tr><tr><td>Nested Economies v3.3</td><td><code>aae656d32f8b45ebf228e6f387d8e461d8767f238219911b8911c2ef95f00b59</code></td></tr><tr><td>Integrated Meta-Governance v1.6</td><td><code>cf1cd81a681b6b94ef4107cee35dfdabb3a991f6472c75d87fa7218a229466ba</code></td></tr><tr><td>Polycentric Governance Architecture v0.6</td><td><code>07e7c19d3c34aaaa4cc85e293c580736dffd0ead9a4055ba8c42cd33ae30e5a0</code></td></tr><tr><td>Hearthstone Protocol v2.0.1</td><td><code>5de218ceb69c486cfa2cb82d9af859bd635854f9c256e9d083b7251f5fd0f0c6</code></td></tr><tr><td>Pathfinder Protocol v0.9</td><td><code>c5cf368ac1908e0d2f5e9cb29f649f14df3d5c7dd8b69b02a28e46a9be828b9f</code></td></tr><tr><td>Bioregional Polis v3.0</td><td><code>264a15a53945217d603db0f374c4867e95eb1ff6d58cc7a53727e26b5373a006</code></td></tr><tr><td>Sundown Protocol v2.1</td><td><code>9968f271528b4f07be7560b0a0f5a4e5f06178e69b7882df49ba71c09bf0f841</code></td></tr><tr><td>Aegis Protocol v1.3.4</td><td><code>9a14ca297c8b179a2528aeb01937c6f88758ef27a91ee8cfe0f2a3a4dde416df</code></td></tr><tr><td>Regenerative Journeys v1.1</td><td><code>dd3d7c2e46aa6c9b5c799fbfdb553af4a88131c9a066d90d5664264cd4fd960f</code></td></tr><tr><td>Religious & Spiritual Dialogue v1.8</td><td><code>79d98d9d857748f18eedb3eb7570d405e877adc38c31fb2a1aa37df8423fac10</code></td></tr><tr><td>Millennium Protocol v1.0</td><td><code>5128c38773291110de6a3c19e5f0d6a0edb0da1934b952323a18ee766e8ceb97</code></td></tr><tr><td>Water & Sanitation Governance v5.2.2</td><td><code>026a3981aa17e75965c888e026f94515b55e1c39dca3299a52a408a22b9c6204</code></td></tr></tbody></table> <p>GMEAIA and the current Indigenous, justice, and data-governance instruments are controlling interfaces where applicable but are not frozen in this draft because their canonical source files were not part of this source set.</p> <h3>Version history</h3> <ul><li><strong>0.1.4 (2026-08-27):</strong> First-receiver incidence patch. Adds §20.6 requiring capitalization deployment, dividend distribution, and social-inheritance disbursement to record first-receiver incidence under Financial Systems §6.6, extending §20.2 asset-price review from the price effect to the sequence that produces it. Clarifies that the record is a distributional disclosure and does not create a beneficiary means test, an eligibility condition, or a fiduciary breach finding.</li> <li><strong>0.1.3 (2026-08-08):</strong> Person-continuity conformance patch to CIS/0.2.4 and Aurora v1.3.2. Makes beneficiary and individual-capital-claim identity explicitly purpose-limited; prohibits universal correlation keys and transitive cross-domain linkage; requires correction for mistaken merges, splits, duplicates, and collisions; and allows externally established death/status events to alter beneficiary or account administration without this Protocol registering death or determining heirs, probate, family status, or inheritance entitlement. Vested/accrued beneficiary claims, challenge rights, pending distributions, remedies, liabilities, and unresolved duties survive until a competent succession or beneficiary process resolves them. Existing SCSI records import the CIS Appendix M minimum where continuity is consequential; no new identity record family or succession jurisdiction is created.</li> <li><strong>0.1.2 (2026-08-07):</strong> Narrow integration revision following second corpus audit. Added Aegis v1.3.4 as a conformance precedent and transition-finance interface; distinguished lawful pension-fund investment from impermissible repurposing of accrued beneficiary claims in pension-backed vehicles; added risk, fiduciary, beneficiary, and loss-allocation conditions for such vehicles. Expanded the Hearthstone interface so that Hearthstone governs the conversion process where a shared-capital institution, endowment, fund, or debt arrangement is itself the object of transition, while this Protocol governs beneficiary, custody, investment-mandate, continuity, and lifecycle consequences. Source draft: v0.1.1 SHA-256 <code>d89457c08273a04fb76c0d919f684c4354a1a55342d59a094268a87276c12f32</code>.</li> <li><strong>0.1.1 (2026-08-07):</strong> Adversarial-integration revision following corpus review. Added Sundown as an investment-policy interface and required divestment or exclusion to arise from a fund mandate, lawful constituting instrument, or voluntary compact rather than a domain-framework indicator. Reclassified pensions as deferred individual lifecycle-capital claims distinct from worker/member pooled capital and added pension prominence to Phase 0. Added existing-fund precedents and migration routes for Regenerative Journeys, Religious & Spiritual Dialogue, Millennium, and Water & Sanitation. Strengthened public-risk/shared-upside rules with ex ante loss tolerance, portfolio-level accounting, write-offs, and anti-cherry-picking requirements. Made explicit why shared capital and social inheritance remain one protocol while preserving a future split boundary. Source draft: v0.1 SHA-256 <code>09d7a3cfa54850b010b85fee81609076f041c2eff4ec7b8050dd0a66decad0b5</code>.</li> <li><strong>0.1 (2026-08-07):</strong> Initial architecture draft. Establishes the distinction between material security and capital ownership; defines plural shared-capital institutions and social inheritance; separates capitalization, custody, investment, beneficiary rights, distribution, and adjudication; provides Phase 0 deployment through existing lawful public and collective assets; creates no self-authorizing public owner; protects Indigenous and community property from automatic commoning; separates tax collection from capital custody; establishes public-risk/shared-upside design options; defines social inheritance as a capital claim rather than an AUBI substitute; and creates falsification, anti-capture, continuity, and closure requirements.</li></ul> <hr> <h1>Executive constitutional summary</h1> <p>A society may guarantee income security and still leave ownership of productive capital highly concentrated.</p> <p>AUBI addresses the first problem. Adaptive Tax addresses the lawful public claim on income, wealth, inheritance, rents, transactions, and other fiscal bases. Hearthstone supplies voluntary and separately lawful pathways for changing ownership form. Pathfinder and Bioregional Polis contain enterprise- and place-specific ownership mechanisms.</p> <p>A separate question remains:</p> <blockquote><p><strong>Who holds productive capital on behalf of people who otherwise possess little or no capital, and how can those claims be distributed without creating a new centralized owner?</strong></p></blockquote> <p>This Protocol governs that question.</p> <p>It provides a common architecture for:</p> <ol><li>national, regional, municipal, BAZ, worker, community, Indigenous, commons, pension-linked, and other lawfully constituted shared-capital funds;</li> <li>public or collective equity, revenue-sharing, royalty, and other capital claims created through lawful investment or agreement;</li> <li>social inheritance, citizen-capital accounts, universal or broadly based capital endowments, and similar mechanisms;</li> <li>collective dividends and reinvestment policies;</li> <li>beneficiary rights, fiduciary governance, investment mandates, voting rights, transparency, and challenge;</li> <li>transition from public expenditure that socializes risk while privatizing all upside toward public-investment arrangements that may retain a lawful share of upside where appropriate;</li> <li>interfaces among fiscal revenue, public capital, voluntary stewardship conversion, worker/community ownership, commons dividends, and AUBI.</li></ol> <p>It does <strong>not</strong> create a global social wealth fund, impose a tax, seize shares, nationalize an enterprise, compel an estate transfer, convert Indigenous or community property into public capital, require a company to issue equity, or make public ownership presumptively superior to private, cooperative, Indigenous, family, stewardship, or other lawful ownership.</p> <p>Three rules govern the Protocol:</p> <blockquote><p><strong>Material security is not the same as capital ownership. AUBI protects the ability to live and refuse; shared capital concerns who receives returns and governing claims from productive assets.</strong></p></blockquote> <blockquote><p><strong>Public purpose does not create public title. A government, fund, BAZ, commons institution, or GGF framework acquires an asset only through an independently valid legal or voluntary route.</strong></p></blockquote> <blockquote><p><strong>Broadening ownership must not culminate in one unchallengeable owner. Shared capital shall remain plural, bounded, fiduciary, contestable, and separable from general political sovereignty.</strong></p></blockquote> <hr> <h1>1. Purpose, problem, and boundaries</h1> <h2>1.1 Purpose</h2> <p>The Protocol enables jurisdictions and communities to broaden capital ownership without treating redistribution of income as the complete solution to economic concentration.</p> <p>Its purposes are to support:</p> <ul><li>broad access to returns from productive capital;</li> <li>intergenerational opportunity;</li> <li>durable household and community balance sheets;</li> <li>public participation in upside where public resources bear entrepreneurial or infrastructure risk;</li> <li>plural collective ownership rather than one centralized state portfolio;</li> <li>worker and community wealth building;</li> <li>common and public wealth that can survive annual budget cycles;</li> <li>long-horizon intergenerational stewardship;</li> <li>non-coercive transition among ownership forms;</li> <li>constitutional separation between economic ownership and political command.</li></ul> <p>The Protocol is agnostic about one universal optimal mix of private, cooperative, public, community, stewardship, family, pension, Indigenous, or commons ownership.</p> <p>Its task is to make shared ownership <strong>legible, lawful, bounded, and accountable</strong> where a competent authority or community chooses it.</p> <h2>1.2 The gap this Protocol owns</h2> <p>The GGF already contains adjacent mechanisms:</p> <ul><li>AUBI provides unconditional material security;</li> <li>Adaptive Tax governs fiscal claims and revenue architecture;</li> <li>Financial Systems governs currencies, reserves, settlement, and financial operations;</li> <li>Nested Economies governs economic subsidiarity and cross-boundary interfaces;</li> <li>Pathfinder proposes enterprise-level profit sharing, ESOPs, Community Investment Trusts, and steward ownership;</li> <li>Bioregional Polis proposes Community Land Trusts, local purchase funds, and land-transition tools;</li> <li>Hearthstone governs voluntary and separately lawful transitions into stewardship and commons forms;</li> <li>the Treaty creates the Global Commons Fund and permits protocols for commons dividends.</li></ul> <p>None of those mechanisms, by itself, provides a general architecture for <strong>plural public and collective capital custody plus broadly distributed capital endowments</strong>.</p> <p>Shared capital and social inheritance remain in one Protocol because the individualized endowment depends on the same custody, fiduciary, beneficiary, investment, accounting, challenge, continuity, and closure machinery as the collective fund that finances or administers it. Splitting them now would duplicate the governance core and obscure the handoff between pooled capital and individualized claims.</p> <p>The seam remains explicit. If later evidence shows that social-inheritance design requires materially different institutions, Sections 11 and 12 are intended to be separable into a sibling protocol without transferring the shared-capital governance core.</p> <p>This Protocol owns that gap and no more.</p> <h2>1.3 What this Protocol does not own</h2> <p>This Protocol does not define:</p> <ul><li>tax rates, tax bases, inheritance tax, wealth tax, or compulsory levies;</li> <li>AUBI entitlement or benefit levels;</li> <li>Hearts or Leaves issuance, reserve, redemption, or demurrage;</li> <li>general corporate law, securities law, pension law, banking law, or competition law;</li> <li>the legality of nationalization, eminent domain, forfeiture, reparations, restitution, or compulsory acquisition;</li> <li>internal Indigenous law, title, succession, or representation;</li> <li>Community Land Trust law;</li> <li>enterprise-level worker-governance standards;</li> <li>general public budgeting;</li> <li>monetary policy;</li> <li>criminal or civil liability;</li> <li>Treaty competence not already conferred;</li> <li>the exact lifecycle states, consequence profiles, response clocks, and closure semantics controlled by GMEAIA.</li></ul> <hr> <h1>2. Core distinctions</h1> <h2>2.1 Income security and capital ownership</h2> <p>A person may receive a secure income while owning no productive capital.</p> <p>AUBI addresses material security. Shared capital addresses ownership claims, investment returns, voting rights where applicable, and intergenerational asset access.</p> <p>The two may complement one another but shall not be merged.</p> <p>A social-inheritance grant:</p> <ul><li>does not replace AUBI Layer 1;</li> <li>does not justify reducing AUBI because the recipient now owns an asset;</li> <li>does not become a reward for contribution;</li> <li>does not imply that every person must become an investor.</li></ul> <h2>2.2 Fiscal flow and capital stock</h2> <p>Adaptive Tax governs lawful fiscal flows into public purposes.</p> <p>This Protocol governs the receiving capital institution where revenue or assets are converted into durable capital stock.</p> <p>A tax authority does not become an investment manager because it collects the revenue. A fund does not acquire taxation authority because it receives public revenue.</p> <h2>2.3 Public expenditure and public investment</h2> <p>A grant, service payment, procurement contract, guarantee, loan, equity investment, royalty, revenue share, and public asset purchase are distinct instruments.</p> <p>Public spending does not automatically create an ownership claim.</p> <p>Where a competent authority chooses to invest rather than grant, the instrument shall state:</p> <ul><li>the public purpose;</li> <li>risk borne;</li> <li>expected financial or non-financial return;</li> <li>ownership or revenue right;</li> <li>duration;</li> <li>governance rights;</li> <li>downside exposure;</li> <li>exit or conversion;</li> <li>treatment of workers, communities, and other investors.</li></ul> <h2>2.4 Collective ownership and individual claim</h2> <p>A shared-capital fund may hold assets collectively without every beneficiary owning a redeemable pro-rata share.</p> <p>A social-inheritance arrangement may instead create an individualized claim.</p> <p>The constituting instrument shall distinguish:</p> <ul><li><strong>collective beneficiary interest</strong> — the person benefits from a fund’s mission or distributions but does not own a directly redeemable share;</li> <li><strong>individual capital claim</strong> — the person owns or controls a legally defined account, share, unit, grant, or other asset;</li> <li><strong>governance standing</strong> — the person has participation, election, challenge, or information rights;</li> <li><strong>title</strong> — the legal owner of the underlying asset.</li></ul> <p>These shall not be collapsed.</p> <h2>2.5 Shared capital and stewardship</h2> <p>Shared capital may be held through ordinary financial, public, cooperative, pension, trust, or other lawful forms.</p> <p>Hearthstone stewardship is a distinct ownership and fiduciary pathway.</p> <p>A public or community capital fund does not become a Hearthstone stewardship entity merely because it has social or ecological objectives. Where an asset transitions into stewardship form, Hearthstone and applicable property law govern that transition.</p> <h2>2.6 Commons revenue and commons ownership</h2> <p>A charge on use of a commons does not by itself determine who owns the commons.</p> <p>A commons dividend or shared-capital fund financed by commons-use revenue shall preserve:</p> <ul><li>Indigenous rights and authority;</li> <li>affected-community standing;</li> <li>ecological obligations;</li> <li>future-generation interests;</li> <li>the distinction between revenue allocation and title.</li></ul> <hr> <h1>3. Constitutional principles</h1> <h2>3.1 No self-authorizing public owner</h2> <p>Nothing in this Protocol independently authorizes any institution to acquire an asset.</p> <p>Acquisition requires a valid route such as:</p> <ul><li>lawful appropriation and purchase;</li> <li>voluntary sale;</li> <li>subscribed investment;</li> <li>voluntary donation or bequest;</li> <li>public equity received under an enacted programme or contract;</li> <li>lawful debt restructuring;</li> <li>a Treaty or public compact within conferred competence;</li> <li>a restitution or reparations process with valid claimant and authority;</li> <li>another independently valid legal instrument.</li></ul> <p>A framework recommendation, inequality metric, concentration score, public subsidy, moral claim, or declaration of regenerative purpose does not itself transfer title.</p> <h2>3.2 Plural shared ownership</h2> <p>The Protocol rejects a default architecture in which one global fund accumulates a controlling share of productive capital.</p> <p>Shared-capital institutions should remain plural across:</p> <ul><li>scale;</li> <li>geography;</li> <li>constituency;</li> <li>legal form;</li> <li>investment mandate;</li> <li>accountability base.</li></ul> <p>Coordination and co-investment may occur without merger.</p> <h2>3.3 No public-owner sovereignty</h2> <p>Owning shares, debt, land, infrastructure, or another asset does not grant a fund general regulatory, policing, taxing, adjudicative, or territorial authority.</p> <p>A public fund’s shareholder rights are shareholder rights.</p> <p>Public regulation must rest on public law, not on covert use of ownership to bypass constitutional process.</p> <h2>3.4 Fiduciary purpose before institutional perpetuation</h2> <p>Every shared-capital institution shall state who or what it serves.</p> <p>It shall not treat:</p> <ul><li>asset growth;</li> <li>portfolio size;</li> <li>institutional survival;</li> <li>number of investees;</li> <li>transaction volume;</li> <li>political access</li></ul> <p>as self-justifying purposes.</p> <p>A fund may validly shrink, distribute assets, split, devolve, merge, or close.</p> <h2>3.5 Shared risk may justify shared upside</h2> <p>Where public resources bear substantial entrepreneurial, financing, guarantee, infrastructure, data, research, or market-creation risk, a competent authority should consider whether part of the upside should remain public or broadly shared.</p> <p>This is a <strong>design question, not an automatic entitlement</strong>.</p> <p>The appropriate instrument may still be a grant, open licence, public service obligation, price condition, royalty, loan, equity stake, revenue share, or no financial return at all.</p> <h2>3.6 Beneficiaries are not political clients</h2> <p>Access to shared-capital distributions, social inheritance, or beneficiary standing shall not depend on:</p> <ul><li>political support;</li> <li>Love Ledger participation;</li> <li>Hearts or Leaves contribution;</li> <li>care work;</li> <li>ecological work;</li> <li>ideological conformity;</li> <li>participation in GGF institutions;</li> <li>generalized reputation;</li> <li>willingness to disclose unrelated personal or relational information.</li></ul> <h2>3.7 No AUBI substitution</h2> <p>A social-inheritance programme or shared-capital dividend shall not be represented as a substitute for AUBI Layer 1.</p> <p>A capital asset may fluctuate, become illiquid, be lost, or require long holding periods. Material security cannot depend on successful investment performance.</p> <h2>3.8 Indigenous and community property is not presumptively public capital</h2> <p>Indigenous, customary, communal, sacred, cultural, and community-held assets do not become available for socialization because the Protocol values shared ownership.</p> <p>No GGF fund, Treaty institution, public agency, BAZ, or social-wealth body may:</p> <ul><li>declare an Indigenous asset globally common;</li> <li>substitute a generic public fund for affected-nation authority;</li> <li>monetize protected knowledge without authority;</li> <li>treat rematriation as capitalization of a public portfolio;</li> <li>impose a standardized fund structure on communal tenure.</li></ul> <p>Indigenous-controlled shared-capital institutions may be created only through the relevant Indigenous authority and law.</p> <h2>3.9 Recognition records are not capital-allocation signals</h2> <p>CIS/0.2.4 governs the Recognition-Record Purpose Firewall.</p> <p>Love Ledger, care, ecological contribution, civic participation, cultural recognition, and analogous records shall not silently become:</p> <ul><li>investment eligibility scores;</li> <li>social-inheritance multipliers;</li> <li>beneficiary reputation;</li> <li>creditworthiness;</li> <li>fraud risk;</li> <li>portfolio access rankings.</li></ul> <p>Where a contribution lawfully generates a financial asset, the purpose-appropriate financial record shall be used rather than reconstructing the asset from the recognition record.</p> <h2>3.10 Indicators do not command investment</h2> <p>An inequality measure, local-ownership percentage, ecological score, LMCI indicator, unemployment rate, strategic-industry classification, or dashboard alert may support review.</p> <p>It does not by itself:</p> <ul><li>order purchase or sale;</li> <li>authorize nationalization;</li> <li>change a beneficiary’s rights;</li> <li>redirect a portfolio;</li> <li>create a compulsory capital allocation;</li> <li>justify exclusion of an enterprise;</li> <li>establish fiduciary breach.</li></ul> <h2>3.11 Intergenerational integrity</h2> <p>A fund created partly for future generations shall identify:</p> <ul><li>current beneficiaries;</li> <li>future or reserve interests;</li> <li>distribution rules;</li> <li>depletion limits;</li> <li>review;</li> <li>emergency access conditions;</li> <li>who may alter those rules.</li></ul> <p>“Future generations” shall not become a rhetorical device for insulating current managers from accountability.</p> <h2>3.12 Conformance is not success</h2> <p>A perfectly documented fund may still:</p> <ul><li>underperform;</li> <li>become politically captured;</li> <li>concentrate ownership;</li> <li>subsidize incumbents;</li> <li>create asset inflation;</li> <li>exclude intended beneficiaries;</li> <li>reduce material exit;</li> <li>increase public financial risk.</li></ul> <p>Independent outcome evaluation remains required.</p> <hr> <h1>4. Institutional forms</h1> <p>The Protocol does not prescribe one institution. A jurisdiction or community may use one or several forms.</p> <h2>4.1 Social wealth fund</h2> <p>A <strong>Social Wealth Fund</strong> is a lawfully constituted fund holding diversified productive or financial assets for a defined public or beneficiary purpose.</p> <p>Possible scales include:</p> <ul><li>national;</li> <li>regional;</li> <li>municipal;</li> <li>BAZ;</li> <li>multi-jurisdiction compact;</li> <li>sectoral.</li></ul> <p>A social wealth fund is not necessarily sovereign and does not require sovereign ownership.</p> <h2>4.2 Community wealth fund</h2> <p>A <strong>Community Wealth Fund</strong> holds assets for a geographically, functionally, or associationally defined community.</p> <p>It may support:</p> <ul><li>local dividends;</li> <li>community investment;</li> <li>acquisition of local enterprises;</li> <li>affordable housing;</li> <li>common infrastructure;</li> <li>long-term reserves.</li></ul> <p>Its beneficiary boundary and exit implications shall be explicit.</p> <h2>4.3 Worker or member capital fund</h2> <p>A worker, union, cooperative, guild, or member institution may pool capital for:</p> <ul><li>worker ownership;</li> <li>enterprise succession;</li> <li>co-investment;</li> <li>mutual development;</li> <li>member-controlled reserves.</li></ul> <p>Work in Liberation and applicable labour, cooperative, securities, and associational law govern the relevant rights.</p> <p>A retirement or pension claim is not classified here merely because workers are its beneficiaries.</p> <h2>4.4 Pension and lifecycle capital institution</h2> <p>A pension system combines two constitutionally distinct objects:</p> <ul><li>a <strong>pooled investment institution</strong> holding assets under a retirement mandate; and</li> <li>a <strong>deferred individual or household capital claim</strong> that vests, accrues, or becomes payable under pension law.</li></ul> <p>The pooled institution may fall within this Protocol where its custody, investment, governance, or public/shared-capital character is relevant. The accrued pension claim remains governed primarily by pension, labour, social-security, tax, insolvency, and financial law.</p> <p>A pension mandate shall not be repurposed into general development, divestment, social-inheritance, or political policy merely because its assets are publicly or collectively managed. Any additional mandate requires the authority and beneficiary protections applicable to the pension system.</p> <p>A <strong>pension-backed vehicle</strong> is therefore not a separate source of public-purpose authority. The term may describe a vehicle in which a pension institution lawfully invests, co-invests, lends, guarantees, or otherwise participates under its existing or lawfully amended mandate. It shall not mean that accrued or vested beneficiary claims may be pledged, subordinated, diverted, or exposed to transition-policy risk merely because the vehicle serves a public purpose. Section 11.12 states the minimum interface conditions.</p> <p>Pensions are therefore a <strong>lifecycle-capital sibling</strong> of social inheritance, not a subtype of worker pooled capital. Section 11.12 governs the comparison.</p> <h2>4.5 Indigenous-controlled capital institution</h2> <p>An Indigenous nation or people may establish its own:</p> <ul><li>development fund;</li> <li>intergenerational trust;</li> <li>resource-revenue fund;</li> <li>community investment vehicle;</li> <li>nation-owned enterprise portfolio;</li> <li>social-inheritance arrangement.</li></ul> <p>This Protocol supplies no representation, beneficiary definition, or internal governance rule on its behalf.</p> <h2>4.6 Commons-return fund</h2> <p>A lawfully constituted commons institution or public authority may dedicate authorized commons-use revenue to a fund for:</p> <ul><li>ecological restoration;</li> <li>affected communities;</li> <li>direct dividends;</li> <li>future-generation reserves;</li> <li>shared infrastructure;</li> <li>other authorized purposes.</li></ul> <p>The fund does not determine commons title merely because it receives the revenue.</p> <h2>4.7 Public innovation or development fund</h2> <p>A public authority may hold equity, royalties, revenue shares, convertible claims, or other lawful instruments arising from:</p> <ul><li>public R&D;</li> <li>concessional finance;</li> <li>guarantees;</li> <li>procurement;</li> <li>infrastructure;</li> <li>industrial policy;</li> <li>market creation.</li></ul> <p>Its mandate shall distinguish financial return from development, access, ecological, resilience, or strategic objectives.</p> <h2>4.8 Citizen-capital or social-inheritance account</h2> <p>A <strong>Citizen-Capital Account</strong> or equivalent individualized arrangement holds a legally defined capital claim for a person.</p> <p>The claim may be funded by:</p> <ul><li>public appropriation;</li> <li>authorized fiscal revenue;</li> <li>fund distributions;</li> <li>gifts or bequests;</li> <li>commons dividends;</li> <li>other lawful sources.</li></ul> <p>The account’s legal ownership, control, access, creditor treatment, tax treatment, and portability shall be explicit.</p> <h2>4.9 Intergenerational reserve or endowment fund</h2> <p>An intergenerational reserve or endowment fund retains capital across time rather than maximizing current distribution.</p> <p>Its charter shall specify:</p> <ul><li>reserve or endowment purpose;</li> <li>drawdown rules;</li> <li>investment horizon;</li> <li>emergency access;</li> <li>beneficiary generations or institutional purpose;</li> <li>amendment threshold;</li> <li>independent review.</li></ul> <p>Long-horizon institutional forms may arise from public law, trusts, foundations, religious or customary endowment traditions, Indigenous law, or other valid constituting systems. The <em>waqf</em> tradition identified by the Religious & Spiritual Dialogue framework is a useful precedent for durable non-state public-purpose capital, but this Protocol does not universalize its legal or religious form.</p> <p>A reserve rule shall not be so rigid that current rights or catastrophic needs become subordinate to institutional preservation.</p> <hr> <h1>5. Function separation</h1> <p>A shared-capital system can accumulate substantial economic power. Its functions therefore require explicit separation.</p> <table><thead><tr><th>Function</th><th>Primary role</th><th>Constitutional limit</th></tr></thead><tbody><tr><td>Constituting authority</td><td>creates the fund and lawful mandate</td><td>does not manage individual trades by default</td></tr><tr><td>Capitalization authority</td><td>appropriates or transfers lawful revenue/assets</td><td>does not infer title from public purpose</td></tr><tr><td>Fiduciary board or trustees</td><td>interpret charter and supervise mandate</td><td>do not legislate general public policy</td></tr><tr><td>Custodian</td><td>holds assets and settlement records</td><td>does not determine beneficiary eligibility or political priorities</td></tr><tr><td>Investment manager</td><td>implements investment mandate</td><td>does not rewrite the mandate or beneficiary rights</td></tr><tr><td>Beneficiary/allocation authority</td><td>applies valid distribution rules</td><td>does not direct portfolio management for partisan purposes</td></tr><tr><td>Auditor</td><td>verifies finance, process, conflicts, and controls</td><td>does not manage the portfolio it audits</td></tr><tr><td>Outcome evaluator</td><td>assesses material effects and theory of change</td><td>does not convert evaluation metrics automatically into trades</td></tr><tr><td>Tribunal or court</td><td>adjudicates disputes within valid jurisdiction</td><td>does not become the fund manager</td></tr><tr><td>Regulator</td><td>applies applicable financial, labour, competition, tax, and other law</td><td>does not use the fund’s ownership as substitute jurisdiction</td></tr></tbody></table> <p>Smaller institutions may combine functions where necessary. Combination shall be disclosed, justified under proportional process, and independently reviewable.</p> <hr> <h1>6. Charter requirements</h1> <p>Every consequential shared-capital institution shall have a charter or equivalent constituting record stating, as applicable:</p> <ol><li>legal form and jurisdiction;</li> <li>constituting authority;</li> <li>purpose;</li> <li>beneficiaries;</li> <li>assets and eligible capitalization sources;</li> <li>prohibited sources;</li> <li>investment mandate;</li> <li>risk tolerance;</li> <li>liquidity requirements;</li> <li>diversification policy;</li> <li>geographic and sectoral scope;</li> <li>local-development or strategic mandate, if any;</li> <li>ecological, labour, rights, and Indigenous constraints;</li> <li>voting and stewardship policy;</li> <li>ownership-concentration limits or review triggers;</li> <li>use of external asset managers;</li> <li>fees and compensation;</li> <li>conflict-of-interest rules;</li> <li>political-independence safeguards;</li> <li>beneficiary participation and challenge;</li> <li>transparency and protected information;</li> <li>dividend, reinvestment, reserve, and social-inheritance rules;</li> <li>treatment of losses;</li> <li>borrowing and leverage limits;</li> <li>valuation and accounting;</li> <li>audit and outcome evaluation;</li> <li>amendment;</li> <li>suspension;</li> <li>succession;</li> <li>dissolution;</li> <li>destination of residual assets;</li> <li>unresolved claims and remedy;</li> <li>GMEAIA authority-effect and consequence profile where applicable.</li></ol> <p>A charter is not proof that the institution should exist.</p> <p><strong>Conformance precedents.</strong> Water & Sanitation v5.2.2 record <code>WAT-16</code> already operationalizes a strong domain-specific version of this architecture: legal custodian, public purpose, eligible uses, fund segregation, procurement, beneficial-ownership disclosure, audit, conflicts, reserves, insolvency, restitution, and dissolution. Aegis v1.3.4 Section 15 supplies a complementary transition-finance precedent: no self-created global trust, separately constituted facilities, and a Transition Finance Facility Charter covering contributors and beneficiaries, custody and investment mandate, eligible missions and exclusions, procurement and conflicts, worker/regional/Indigenous/environmental/reparative allocations, risk and loss allocation, audit, complaint, withdrawal, insolvency, succession, and dissolution. New shared-capital charters should reuse or exceed such existing controls rather than develop weaker parallel templates.</p> <hr> <h1>7. Capitalization</h1> <h2>7.1 Lawful capitalization sources</h2> <p>A fund may receive assets through a valid route including:</p> <ul><li>legislative or municipal appropriation;</li> <li>revenue transferred under Adaptive Tax;</li> <li>authorized commons-use revenue;</li> <li>dividends or returns from existing public assets;</li> <li>public equity, royalties, or revenue shares;</li> <li>proceeds from lawful public asset transactions;</li> <li>voluntary donations;</li> <li>voluntary bequests;</li> <li>Hearthstone-supported voluntary transitions;</li> <li>negotiated employee, community, or enterprise contributions;</li> <li>lawful debt restructuring;</li> <li>public procurement or licensing agreements;</li> <li>restitution or reparations assets where the claimant and competent authority choose that form;</li> <li>Treaty or compact transfers within conferred competence;</li> <li>other lawful capitalization.</li></ul> <h2>7.2 Prohibited capitalization by implication</h2> <p>The following do not by themselves create a fund asset:</p> <ul><li>an inequality threshold;</li> <li>a wealth estimate;</li> <li>a finding of corporate dominance;</li> <li>ecological importance;</li> <li>public subsidy received in the past;</li> <li>use of public infrastructure;</li> <li>worker contribution;</li> <li>participation in AUBI;</li> <li>Love Ledger recognition;</li> <li>Indigenous or community stewardship;</li> <li>classification as a “commons” by a GGF framework;</li> <li>non-participation in GGF systems.</li></ul> <p>Where these facts justify public policy, the policy still requires a separately valid instrument.</p> <h2>7.3 Adaptive Tax interface</h2> <p>Adaptive Tax owns:</p> <ul><li>compulsory fiscal collection;</li> <li>tax and inheritance bases;</li> <li>valuation for tax purposes;</li> <li>fiscal credits;</li> <li>tax enforcement;</li> <li>revenue-sharing arrangements.</li></ul> <p>This Protocol owns:</p> <ul><li>acceptance of transferred revenue into capital custody;</li> <li>investment of that capital;</li> <li>beneficiary and governance rights;</li> <li>distribution or reinvestment.</li></ul> <p>Earmarking tax revenue to a fund requires the same authority and budget discipline as any other fiscal dedication.</p> <h2>7.4 Treaty and Global Commons Fund interface</h2> <p>Treaty Article 18.4 creates the Global Commons Fund for authorized global public goods and related purposes.</p> <p>This Protocol does not convert the GCF into a planetary social wealth fund.</p> <p>Treaty Article 18.6 permits protocols distributing part of authorized commons-use revenue directly or collectively to people and affected communities. A future Treaty-compatible shared-capital mechanism may use that route only where:</p> <ul><li>the revenue class is authorized;</li> <li>the protocol is lawfully adopted;</li> <li>ownership and stewardship are separately addressed;</li> <li>Indigenous and affected-community rights are preserved;</li> <li>non-member and future-generation effects are addressed.</li></ul> <h2>7.5 Public risk and upside</h2> <p>Where a public authority provides:</p> <ul><li>early-stage R&D;</li> <li>concessional finance;</li> <li>guarantee;</li> <li>infrastructure;</li> <li>exclusive licence;</li> <li>procurement commitment;</li> <li>market-making support;</li> <li>other material risk-bearing assistance,</li></ul> <p>the constituting process should explicitly consider whether the appropriate public return is:</p> <ul><li>none;</li> <li>repayment;</li> <li>interest;</li> <li>royalty;</li> <li>revenue share;</li> <li>equity;</li> <li>warrant or convertible claim;</li> <li>open licensing;</li> <li>price or access condition;</li> <li>public-service obligation;</li> <li>mixed return.</li></ul> <p>No universal equity formula applies.</p> <p>Where the selected instrument exposes public capital to investment loss, the authorizing record shall also state, proportionate to scale and uncertainty:</p> <ul><li>the expected or accepted loss range and its evidentiary basis;</li> <li>the portfolio or programme across which risk is being accepted;</li> <li>maximum loss or capital-at-risk limits where applicable;</li> <li>follow-on funding and dilution policy;</li> <li>write-off and impairment rules;</li> <li>whether non-financial public benefits may justify below-market financial return;</li> <li>the benchmark or comparator against which the arrangement will be evaluated;</li> <li>the review or termination condition if losses or administrative burdens exceed the mandate.</li></ul> <p>Public-equity and shared-upside programmes shall be evaluated at <strong>portfolio or programme level</strong>, not by publicizing successful holdings while excluding failures, write-offs, subsidies, fees, guarantees, or opportunity costs. Reports shall disclose both realized and material unrealized gains and losses under a consistent accounting policy.</p> <blockquote><p><strong>Shared upside requires shared accounting of downside. A celebrated winner does not erase the portfolio that paid for it.</strong></p></blockquote> <h2>7.6 No retrospective ownership inference</h2> <p>A past subsidy, tax benefit, research grant, bailout, or infrastructure investment does not retroactively create an equity claim unless the governing law or agreement already did so or a new lawful settlement is reached.</p> <hr> <h1>8. Investment mandate and portfolio governance</h1> <h2>8.1 Mandate before optimization</h2> <p>An investment manager shall optimize only within the legally constituted mandate.</p> <p>A mandate may prioritize some combination of:</p> <ul><li>long-term financial return;</li> <li>capital preservation;</li> <li>inflation protection;</li> <li>intergenerational wealth;</li> <li>local development;</li> <li>strategic resilience;</li> <li>affordable housing;</li> <li>worker ownership;</li> <li>ecological restoration;</li> <li>public innovation;</li> <li>transition finance;</li> <li>liquidity;</li> <li>diversification.</li></ul> <p>Trade-offs shall be explicit.</p> <h2>8.2 No universal return benchmark</h2> <p>A community-development fund, pension-linked fund, national reserve fund, and social-inheritance fund need not share one benchmark.</p> <p>Evaluation should distinguish:</p> <ul><li>financial return;</li> <li>risk;</li> <li>liquidity;</li> <li>public subsidy;</li> <li>development effects;</li> <li>ownership broadening;</li> <li>distribution;</li> <li>ecological and labour effects;</li> <li>crowding in or crowding out;</li> <li>administrative cost.</li></ul> <h2>8.3 Diversification and concentration</h2> <p>Shared capital can itself become a source of concentration.</p> <p>Each fund shall consider:</p> <ul><li>issuer concentration;</li> <li>sector concentration;</li> <li>geographic concentration;</li> <li>manager concentration;</li> <li>index-provider dependence;</li> <li>platform and custodian dependence;</li> <li>public-sector concentration;</li> <li>correlated climate, technology, or commodity exposure;</li> <li>voting-power concentration.</li></ul> <p>A concentration threshold may trigger review. It does not automatically require sale.</p> <h2>8.4 Local and strategic investment</h2> <p>A fund may have a lawful mandate to invest locally or strategically.</p> <p>Such a mandate shall state:</p> <ul><li>why geographic or strategic concentration is justified;</li> <li>expected public benefit;</li> <li>risk;</li> <li>additionality;</li> <li>political-selection safeguards;</li> <li>procurement and competition interfaces;</li> <li>exit conditions;</li> <li>how failed investments are treated.</li></ul> <p>“Invest locally” shall not become a licence for patronage.</p> <h2>8.5 External managers</h2> <p>External asset managers shall disclose:</p> <ul><li>ownership;</li> <li>fees;</li> <li>conflicts;</li> <li>voting policy;</li> <li>securities lending;</li> <li>related-party transactions;</li> <li>political contributions where disclosure is lawful;</li> <li>subcontractors;</li> <li>data and AI systems;</li> <li>termination rights.</li></ul> <p>A public fund should retain the practical ability to change managers without losing custody of its own records or assets.</p> <h2>8.6 Leverage and derivatives</h2> <p>Borrowing, leverage, securities lending, derivatives, and other complex instruments require explicit authorization proportionate to the fund’s purpose and risk.</p> <p>A social-inheritance or essential-beneficiary fund shall not rely on opaque leverage merely to increase headline returns.</p> <h2>8.7 Automated investment</h2> <p>Automation may execute portfolio rules, rebalance, monitor risk, or assist analysis where lawfully authorized.</p> <p>Automation shall not independently:</p> <ul><li>rewrite the mandate;</li> <li>change beneficiary rights;</li> <li>classify political loyalty;</li> <li>bypass protected non-transfer;</li> <li>create a new strategic objective;</li> <li>convert an exploratory metric into a compulsory investment instruction.</li></ul> <p>Material model changes are governance changes.</p> <hr> <h2>8.8 External divestment, exclusion, and transition mandates</h2> <p>A domain framework, certification system, transition dashboard, ecological indicator, or external campaign does not alter a fund’s investment mandate merely by identifying an issuer or sector as non-compliant, harmful, or transition-relevant.</p> <p>A shared-capital institution may divest, exclude new investment, coordinate stewardship, or join a common transition policy where the action arises from one of the following:</p> <ol><li>an exclusion or transition rule already contained in its lawful constituting instrument or investment mandate;</li> <li>a lawful amendment by the authority competent to change that mandate;</li> <li>generally applicable law binding the fund;</li> <li>a voluntary compact into which the fund or its competent authority has validly entered;</li> <li>a rights, sanctions, adjudicative, or other external legal obligation independently binding on the fund.</li></ol> <p>Where an external indicator triggers review under such a mandate, the indicator remains evidence or a defined contractual input; it is not itself the source of the investment power. The record shall distinguish:</p> <ul><li>the external finding or classification;</li> <li>the fund’s own legal or contractual rule giving that finding effect;</li> <li>the act authorized: engagement, voting, no-new-investment, staged divestment, immediate divestment, or another response;</li> <li>beneficiary and portfolio consequences;</li> <li>transition timing and liquidity;</li> <li>review, challenge, expiry, or re-entry conditions.</li></ul> <p>Coordinated divestment among voluntarily participating funds is a coordination compact. A statement by another GGF framework that ‘public funds divest’ is not such a compact and is not an investment instruction.</p> <h1>9. Ownership and voting rights</h1> <h2>9.1 Ownership rights shall be stated</h2> <p>Where a fund owns shares or another governing interest, the charter shall state whether it may exercise:</p> <ul><li>ordinary voting;</li> <li>board nomination;</li> <li>shareholder proposals;</li> <li>stewardship engagement;</li> <li>veto or consent rights created by the instrument;</li> <li>litigation;</li> <li>exit.</li></ul> <p>The fund shall not pretend to be a passive financial holder while exercising undisclosed control.</p> <h2>9.2 Public ownership is not regulation</h2> <p>A public fund may vote as an owner within its valid rights.</p> <p>It may not use ownership to impose obligations that the public authority lacks power to enact generally where doing so would evade:</p> <ul><li>law;</li> <li>rights;</li> <li>procurement rules;</li> <li>competition safeguards;</li> <li>labour process;</li> <li>Indigenous authority;</li> <li>due process.</li></ul> <h2>9.3 Voting policy</h2> <p>A fund exercising shareholder rights shall publish a voting or stewardship policy covering, as relevant:</p> <ul><li>worker rights;</li> <li>executive compensation;</li> <li>dilution;</li> <li>related-party transactions;</li> <li>takeover protections;</li> <li>climate and ecological risk;</li> <li>political expenditure disclosure;</li> <li>audit;</li> <li>board independence;</li> <li>human-rights risk;</li> <li>shareholder rights.</li></ul> <p>The policy may not convert one contested metric into automatic voting.</p> <h2>9.4 Control review</h2> <p>Where one or several public/shared funds acquire material control over an enterprise, infrastructure system, sector, or market, an independent review shall consider:</p> <ul><li>regulatory separation;</li> <li>competition;</li> <li>minority investors;</li> <li>workers;</li> <li>customers and users;</li> <li>political influence;</li> <li>state-aid or subsidy issues;</li> <li>exit;</li> <li>whether ownership has become de facto administrative command.</li></ul> <p>Control does not itself prove harm. It increases the need for explicit boundaries.</p> <hr> <h1>10. Beneficiary constitution and rights</h1> <h2>10.1 Beneficiary definition</h2> <p>Each institution shall define who qualifies as a beneficiary and why.</p> <p>Possible bases include:</p> <ul><li>residence;</li> <li>citizenship;</li> <li>membership;</li> <li>employment;</li> <li>Indigenous nation membership as determined by the nation;</li> <li>geographic community;</li> <li>age cohort;</li> <li>affected-community status;</li> <li>universal population standing;</li> <li>future-generation reserve interest.</li></ul> <p>The Protocol does not impose one universal beneficiary rule.</p> <h2>10.2 Beneficiary rights</h2> <p>Depending on the legal form, beneficiaries should have rights to:</p> <ul><li>know the fund’s purpose;</li> <li>access public holdings and performance information;</li> <li>know fees and conflicts;</li> <li>understand whether they own an individual claim;</li> <li>receive distributions according to published rules;</li> <li>challenge factual errors;</li> <li>challenge unlawful exclusion;</li> <li>use accessible and low-technology channels;</li> <li>seek independent review;</li> <li>know amendment and closure rules.</li></ul> <p>Beneficiary standing does not necessarily create a right to direct individual investments.</p> <h2>10.3 Participation</h2> <p>Beneficiary governance may include:</p> <ul><li>elections;</li> <li>sortition;</li> <li>advisory councils;</li> <li>worker or community seats;</li> <li>beneficiary assemblies;</li> <li>public consultation;</li> <li>independent fiduciaries;</li> <li>Indigenous authority where the affected people constitute the institution.</li></ul> <p>No fixed global seat formula is required.</p> <p>Participation design shall not allow organized minorities, incumbent managers, government appointees, or large beneficiaries to capture the whole fund.</p> <h2>10.4 Personal information</h2> <p>Beneficiary administration shall minimize personal data.</p> <p>A fund shall not require unrelated:</p> <ul><li>care histories;</li> <li>Love Ledger records;</li> <li>political beliefs;</li> <li>spiritual or cultural beliefs;</li> <li>health information beyond a valid purpose;</li> <li>migration information beyond a valid eligibility or legal requirement;</li> <li>contribution scores.</li></ul> <p>Institutional holdings and governance should be more transparent than beneficiaries’ private lives.</p> <h2>10.5 Beneficiary identity and person continuity</h2> <p>A beneficiary, account holder, claimant, pension participant, or distribution recipient may be identified through a purpose-limited local identifier or attestation where general civil identity is unnecessary or unavailable.</p> <p>The fund or programme shall not require one universal identifier across AUBI, tax, housing, migration, health, justice, employment, Love Ledger, financial, or civic systems.</p> <p>Where another system and this Protocol must recognize that two bounded records concern the same person:</p> <ul><li>the linkage requires separate authority and a stated beneficiary/account purpose;</li> <li>disclosure is limited to the minimum fields necessary;</li> <li>the relation is <strong>non-transitive by default</strong>;</li> <li>the source records remain distinct;</li> <li>mistaken merge, mistaken split, duplicate, collision, correction, and unlinking must be supported;</li> <li>a continuity assertion does not establish citizenship, migration status, family relation, legal capacity, inheritance entitlement, creditworthiness, reputation, or any unrelated eligibility fact.</li></ul> <p>Where an externally competent authority establishes death, legal-name correction, guardianship change, or another status transition relevant to a beneficiary/account relationship, the receiving fund may update only its own lawful consequences.</p> <p>Death does not automatically:</p> <ul><li>erase vested or accrued beneficiary claims;</li> <li>erase pending distributions, refunds, correction requests, appeals, remedies, or liabilities;</li> <li>determine heirs, successors, pension beneficiaries, or estate ownership;</li> <li>authorize transfer of an individualized capital claim to the fund itself;</li> <li>close unresolved duties merely because the beneficiary has died.</li></ul> <p>Any inheritance, probate, beneficiary-designation, family-status, or succession question outside the fund’s valid constituting instrument is referred to the competent authority. CIS/0.2.4 Appendix M may be embedded in SCSI-02, SCSI-11, SCSI-19, or SCSI-20 where person continuity is consequential rather than creating a parallel identity record.</p> <hr> <h1>11. Social inheritance</h1> <h2>11.1 Purpose</h2> <p><strong>Social inheritance</strong> is a broadly distributed capital claim intended to reduce the extent to which access to capital depends entirely on family wealth, inheritance, or early-life market position.</p> <p>It is capital policy, not a moral reward.</p> <h2>11.2 Relationship to private inheritance</h2> <p>This Protocol does not abolish, limit, or tax private inheritance.</p> <p>Adaptive Tax governs inheritance and gift taxation where lawfully adopted.</p> <p>Hearthstone governs voluntary bequests into stewardship arrangements.</p> <p>Social inheritance asks a separate question: whether a public or collective system should provide a capital endowment to people who qualify under a lawfully adopted programme.</p> <h2>11.3 Design forms</h2> <p>A social-inheritance arrangement may take forms including:</p> <ul><li>unconditional adulthood capital grant;</li> <li>diversified citizen-capital account;</li> <li>non-transferable or time-vested public-fund units;</li> <li>housing or land-capital endowment;</li> <li>cooperative or community-share allocation;</li> <li>education, enterprise, or mobility capital account;</li> <li>mixed account with a protected core and flexible portion.</li></ul> <p>The Protocol does not select one form universally.</p> <h2>11.4 Universal or broad-based presumption</h2> <p>A social-inheritance system intended to counter inherited asset inequality should normally use universal or broad, rule-based eligibility rather than discretionary judgments of deservingness.</p> <p>Targeted supplements may address:</p> <ul><li>historic exclusion;</li> <li>disability;</li> <li>dispossession;</li> <li>care burdens;</li> <li>childhood deprivation;</li> <li>reparative claims;</li> <li>other lawfully recognized inequities.</li></ul> <p>Targeting shall not turn the baseline into behavioural surveillance.</p> <h2>11.5 No contribution requirement</h2> <p>Eligibility shall not depend on:</p> <ul><li>work history;</li> <li>care hours;</li> <li>Hearts earned;</li> <li>Leaves earned;</li> <li>Love Ledger activity;</li> <li>volunteer service;</li> <li>voting;</li> <li>military or civic service;</li> <li>political participation.</li></ul> <p>A jurisdiction may create separate matched-savings or contribution programmes, but they are not the universal social-inheritance baseline merely because they involve capital.</p> <h2>11.6 Age and access</h2> <p>A programme shall specify:</p> <ul><li>when the claim vests;</li> <li>when it becomes accessible;</li> <li>whether staged access applies;</li> <li>rules for minors;</li> <li>disability and supported-decision arrangements;</li> <li>death before vesting;</li> <li>unclaimed accounts;</li> <li>portability.</li></ul> <p>Age thresholds are policy choices requiring justification, not universal constants.</p> <h2>11.7 Restricted and unrestricted use</h2> <p>A jurisdiction may choose:</p> <ul><li>unrestricted capital;</li> <li>use-limited capital;</li> <li>staged release;</li> <li>diversified-account retention;</li> <li>hybrid designs.</li></ul> <p>Restrictions shall be evaluated for:</p> <ul><li>paternalism;</li> <li>administrative burden;</li> <li>market inflation;</li> <li>unequal access to approved uses;</li> <li>disability effects;</li> <li>geographic inequality;</li> <li>ability to challenge a denial.</li></ul> <p>A “wealth-building” restriction that merely channels public money into already supply-constrained housing or education may increase asset prices rather than ownership opportunity.</p> <h2>11.8 Debt and creditor interface</h2> <p>The programme shall explicitly decide whether and when an individualized social-inheritance claim is:</p> <ul><li>attachable by creditors;</li> <li>counted in insolvency;</li> <li>available for child-support or other lawful claims;</li> <li>protected for a period after vesting;</li> <li>protected before vesting;</li> <li>usable as collateral.</li></ul> <p>The Protocol creates no universal creditor exemption.</p> <p>However, a design whose grants are routinely captured immediately by predatory debt, fees, or fraud fails its wealth-broadening purpose even if legally compliant.</p> <h2>11.9 Tax treatment</h2> <p>Adaptive Tax or applicable domestic law governs tax treatment.</p> <p>This Protocol does not presume that:</p> <ul><li>the grant is taxable income;</li> <li>appreciation is tax-free;</li> <li>withdrawals are taxable;</li> <li>transfers are exempt.</li></ul> <p>The treatment shall be explicit before implementation.</p> <h2>11.10 AUBI interaction</h2> <p>A social-inheritance asset shall not automatically:</p> <ul><li>reduce AUBI Layer 1;</li> <li>convert AUBI into means testing;</li> <li>require Hearts use;</li> <li>replace disability or care support;</li> <li>establish contribution worth.</li></ul> <p>If another lawful programme is asset-tested, its interaction must be disclosed rather than hidden inside social inheritance.</p> <h2>11.11 Financial capability without coercion</h2> <p>Programmes should provide accessible financial education, independent advice, fraud protection, and low-fee default options.</p> <p>Completion of education shall not be a condition of basic beneficiary status unless the governing law explicitly and proportionately requires it.</p> <p>People may lawfully choose conservative, low-return, or non-optimized uses.</p> <hr> <h2>11.12 Pensions and other lifecycle capital claims</h2> <p>Pensions and social inheritance are distinct programmes but share a lifecycle-capital interface. Both can involve:</p> <ul><li>vesting;</li> <li>portability;</li> <li>beneficiary designation;</li> <li>creditor and insolvency protection;</li> <li>tax treatment;</li> <li>disability and supported decision-making;</li> <li>cross-jurisdiction movement;</li> <li>default investment;</li> <li>long-horizon custody;</li> <li>claims that become individually exercisable only after a defined event.</li></ul> <p>The distinction is purpose and entitlement structure. A pension generally defers compensation, contributions, social-insurance entitlement, or retirement provision toward later-life income security. Social inheritance is a broadly distributed capital endowment intended to widen initial or lifecycle access to wealth.</p> <p>This Protocol therefore does not absorb pension governance. It requires the interface to remain explicit where:</p> <ul><li>a pension fund is treated as a shared-capital institution;</li> <li>a social-inheritance account is designed using pension-like custody or vesting;</li> <li>a policy proposes to redirect pension assets toward development, transition, or public-investment objectives;</li> <li>social-inheritance assets affect pension eligibility or vice versa.</li></ul> <p>Accrued or vested pension rights are protected beneficiary claims. A shared-capital policy shall not raid, subordinate, convert, or repurpose them merely because the underlying portfolio is collectively managed.</p> <p>Where a transition, development, infrastructure, or public-purpose arrangement is described as <strong>pension-backed</strong>, the constituting record shall distinguish the pension institution’s portfolio decision from the beneficiary’s deferred claim and shall state at least:</p> <ol><li>the pension law, charter, fiduciary mandate, or beneficiary authorization permitting the investment or financing exposure;</li> <li>whether participation is equity, debt, guarantee, collateral, project finance, or another instrument;</li> <li>the expected return, liquidity, duration, concentration, and loss profile relative to the pension mandate;</li> <li>whether any accrued or vested claim is pledged, subordinated, delayed, impaired, or exposed to recourse—and if so, the independently valid authority permitting that effect;</li> <li>independent fiduciary and conflict review;</li> <li>portfolio-level accounting of gains, losses, guarantees, fees, and opportunity cost;</li> <li>beneficiary notice, representation, challenge, and remedy where the exposure is material;</li> <li>exit, reversion, insolvency, and continuity arrangements.</li></ol> <p>A public-purpose benefit, Aegis transition objective, Sundown objective, climate objective, regional-development objective, or other framework goal does not substitute for pension fiduciary authority. If a vehicle cannot be funded without weakening accrued beneficiary claims outside the pension mandate, it shall use another financing route.</p> <h1>12. Collective dividends</h1> <h2>12.1 Distribution choices</h2> <p>A shared-capital institution may:</p> <ul><li>reinvest all returns;</li> <li>distribute all returns;</li> <li>maintain reserves;</li> <li>pay periodic dividends;</li> <li>finance social inheritance;</li> <li>fund authorized public or community goods;</li> <li>use a mixed policy.</li></ul> <p>No universal distribution ratio applies.</p> <h2>12.2 Dividend rights</h2> <p>Where a charter establishes a beneficiary dividend, the rule shall state:</p> <ul><li>eligible beneficiaries;</li> <li>calculation;</li> <li>timing;</li> <li>reserve priority;</li> <li>treatment of losses;</li> <li>portability;</li> <li>correction;</li> <li>unclaimed distributions;</li> <li>tax treatment;</li> <li>amendment.</li></ul> <p>A dividend shall not become a loyalty payment.</p> <h2>12.3 Commons dividends</h2> <p>Treaty Article 18.6 permits protocols for direct or collective distribution of authorized commons-use revenue.</p> <p>Where such revenue is capitalized rather than immediately distributed, the constituting instrument shall explain why delayed or collective ownership better serves:</p> <ul><li>affected communities;</li> <li>ecological restoration;</li> <li>current beneficiaries;</li> <li>future generations.</li></ul> <p>Capitalization does not extinguish any claimant’s independent legal rights.</p> <hr> <h1>13. Worker and community ownership interface</h1> <h2>13.1 Pathfinder and Regenerative Enterprise</h2> <p>Pathfinder already proposes enterprise-level:</p> <ul><li>profit sharing;</li> <li>ESOPs;</li> <li>Community Investment Trusts;</li> <li>steward ownership;</li> <li>local investment.</li></ul> <p>Those mechanisms remain enterprise-transition tools.</p> <p>This Protocol may support them through:</p> <ul><li>co-investment funds;</li> <li>acquisition finance;</li> <li>patient capital;</li> <li>diversification pools;</li> <li>succession funds;</li> <li>public matching capital.</li></ul> <p>It does not rewrite the enterprise’s internal worker-governance rules.</p> <h2>13.2 Work in Liberation</h2> <p>Work in Liberation governs worker rights and labour institutions.</p> <p>A shared-capital fund investing in worker ownership shall preserve:</p> <ul><li>informed worker participation;</li> <li>wages and collective bargaining;</li> <li>pension rights;</li> <li>diversification protections;</li> <li>safe refusal;</li> <li>minority-worker protections;</li> <li>continuity during conversion.</li></ul> <p>Worker ownership shall not be financed by shifting excessive downside risk onto workers whose wages already depend on the same enterprise.</p> <h2>13.3 Bioregional Polis</h2> <p>Bioregional Polis owns municipal land-transition and Community Land Trust architecture.</p> <p>A Community Purchase Fund or local investment vehicle may conform to this Protocol where it holds pooled financial capital.</p> <p>Land title, zoning, CLT governance, right of first refusal, and compulsory public-law tools remain with their competent frameworks and law.</p> <h2>13.4 Hearthstone</h2> <p>Hearthstone governs voluntary or separately lawful asset transition.</p> <p>A shared-capital fund may:</p> <ul><li>purchase an asset voluntarily;</li> <li>finance a cooperative conversion;</li> <li>receive a voluntary bequest;</li> <li>invest in a stewardship entity where lawful;</li> <li>support an authorized public purchase.</li></ul> <p>The fund does not acquire Hearthstone’s transition role, and Hearthstone does not acquire investment authority merely because a transition requires capital.</p> <hr> <h1>14. Indigenous, reparative, and community boundaries</h1> <h2>14.1 No universal Indigenous fund</h2> <p>The GGF shall not create one fund and declare it the capital representative of Indigenous peoples.</p> <p>Affected nations determine:</p> <ul><li>whether to participate;</li> <li>whether to establish a fund;</li> <li>beneficiaries;</li> <li>governance;</li> <li>asset classes;</li> <li>distributions;</li> <li>data;</li> <li>relation to territory and rematriation.</li></ul> <h2>14.2 Reparations and restitution</h2> <p>Reparations or restitution may include:</p> <ul><li>land;</li> <li>financial capital;</li> <li>enterprise equity;</li> <li>endowments;</li> <li>revenue rights;</li> <li>trust assets;</li> <li>other remedies.</li></ul> <p>This Protocol may govern a receiving shared-capital institution only where the claimant and competent authority choose that form.</p> <p>A reparations claim shall not be converted into a pooled social-wealth fund merely because pooling appears economically efficient.</p> <h2>14.3 Rematriation</h2> <p>Rematriated assets are governed by the affected Indigenous people and applicable law.</p> <p>They are not presumed available for public diversification, collateralization, or social-inheritance funding.</p> <h2>14.4 Protected knowledge and data</h2> <p>Indigenous, community, cultural, and sacred knowledge shall not be capitalized, securitized, licensed, or treated as an investment asset without the required authority and consent.</p> <p>Public claims about “knowledge commons” do not override protected non-transfer.</p> <hr> <h1>15. Cross-jurisdiction and Nested Economies interface</h1> <h2>15.1 Local authority and cross-border investment</h2> <p>A local or BAZ fund may invest outside its territory where lawful.</p> <p>A national or global institution may invest locally only within:</p> <ul><li>applicable law;</li> <li>property and securities rules;</li> <li>Indigenous authority;</li> <li>local public authority;</li> <li>the fund’s charter.</li></ul> <p>Investment does not create territorial jurisdiction.</p> <h2>15.2 Cross-scale compacts</h2> <p>Two or more authorities may create:</p> <ul><li>co-investment funds;</li> <li>shared infrastructure funds;</li> <li>regional development funds;</li> <li>portability compacts;</li> <li>common custody or administration;</li> <li>pooled risk arrangements.</li></ul> <p>Nested Economies governs the political and constitutional conditions of the compact.</p> <p>This Protocol governs the capital institution itself.</p> <h2>15.3 Material exit</h2> <p>Cross-jurisdiction funds shall address whether participants can exit in practice.</p> <p>The record should include:</p> <ul><li>withdrawal rights;</li> <li>lock-ups;</li> <li>asset division;</li> <li>continuing liabilities;</li> <li>beneficiary rights;</li> <li>data custody;</li> <li>stranded investments;</li> <li>essential-service dependencies;</li> <li>dispute resolution.</li></ul> <p>A nominal right to withdraw is not meaningful if the participant must abandon essential infrastructure or its own records.</p> <h2>15.4 Non-members</h2> <p>A non-participating jurisdiction does not become a beneficiary, investor, debtor, or regulated party merely because a fund has regional or global ambitions.</p> <p>Any material effect on non-members requires an independently valid basis.</p> <hr> <h1>16. Phase 0 — capital mapping before new institutions</h1> <p>Phase 0 is the default starting point.</p> <p>A jurisdiction does not need a new social wealth fund to begin broadening ownership.</p> <h2>16.1 Map what already exists</h2> <p>Pensions are mapped first rather than treated as one minor public holding. In many economies, pension entitlements are already the largest broad-based household claim on productive capital. Phase 0 therefore records both <strong>the assets held by pension institutions</strong> and <strong>the deferred claims owed to beneficiaries</strong> before concluding that ordinary people hold little or no capital.</p> <p>Phase 0 identifies:</p> <ul><li>public, occupational, collective, and other pension assets together with their accrued or vested beneficiary claims;</li> <li>sovereign or municipal holdings;</li> <li>development banks;</li> <li>public enterprises;</li> <li>public endowments;</li> <li>cooperative funds;</li> <li>worker funds;</li> <li>Community Land Trust capital;</li> <li>community foundations;</li> <li>Indigenous-controlled funds where the nation chooses inclusion;</li> <li>public equity and royalty rights;</li> <li>dormant public financial claims;</li> <li>public guarantees and concessional finance;</li> <li>procurement and R&D programmes that bear risk without retaining upside;</li> <li>existing youth, savings, inheritance, or capital-account programmes.</li></ul> <p>The map distinguishes:</p> <ul><li>legal owner;</li> <li>beneficial purpose;</li> <li>manager;</li> <li>custodian;</li> <li>beneficiaries;</li> <li>risk;</li> <li>liquidity;</li> <li>voting rights;</li> <li>public obligations;</li> <li>exit and dissolution;</li> <li>whether the asset represents unrestricted public capital, fiduciary capital held for beneficiaries, or an individualized deferred claim;</li> <li>whether policy can lawfully change the investment mandate without impairing accrued rights.</li></ul> <h2>16.2 Phase 0 governance audit</h2> <p>Existing institutions may be audited for:</p> <ul><li>mandate clarity;</li> <li>conflicts;</li> <li>fees;</li> <li>political interference;</li> <li>concentration;</li> <li>beneficiary voice;</li> <li>public transparency;</li> <li>private-manager dependence;</li> <li>voting policy;</li> <li>common-mode infrastructure risk;</li> <li>intergenerational drawdown;</li> <li>material exit;</li> <li>whether public risk already generates public upside.</li></ul> <p>The audit creates no authority to seize, merge, or redirect an existing fund.</p> <h2>16.3 Phase 0 public-risk review</h2> <p>Before creating new taxes or compulsory ownership measures, a jurisdiction may review future:</p> <ul><li>R&D grants;</li> <li>guarantees;</li> <li>procurement;</li> <li>concessional loans;</li> <li>infrastructure partnerships;</li> <li>bailout facilities</li></ul> <p>to determine whether appropriately designed future agreements should retain:</p> <ul><li>repayment;</li> <li>equity;</li> <li>royalty;</li> <li>revenue share;</li> <li>open-access rights;</li> <li>public-service conditions.</li></ul> <p>Existing contracts remain governed by their own terms.</p> <h2>16.4 Phase 0 model charters</h2> <p>A jurisdiction or community may develop and simulate:</p> <ul><li>social wealth fund charters;</li> <li>community fund charters;</li> <li>voting policies;</li> <li>social-inheritance accounts;</li> <li>distribution rules;</li> <li>beneficiary governance;</li> <li>dissolution plans;</li> <li>public-equity instruments.</li></ul> <p>A model charter has no authority effect.</p> <h2>16.5 Phase 0 voluntary capitalization</h2> <p>Where lawful, early pilots may use:</p> <ul><li>voluntary public appropriation;</li> <li>philanthropy;</li> <li>donations;</li> <li>bequests;</li> <li>voluntary enterprise participation;</li> <li>existing public asset returns;</li> <li>pilot co-investment.</li></ul> <p>Participation shall not be misrepresented as evidence that compulsory scaling is legitimate.</p> <h2>16.6 Phase 0 social-inheritance simulation</h2> <p>Before real distribution, simulation should test:</p> <ul><li>grant size;</li> <li>age;</li> <li>eligibility;</li> <li>investment default;</li> <li>fees;</li> <li>asset inflation;</li> <li>debt capture;</li> <li>geographic effects;</li> <li>take-up;</li> <li>disability access;</li> <li>interaction with AUBI and existing benefits;</li> <li>fiscal sustainability;</li> <li>inheritance-tax interaction;</li> <li>distributional outcomes.</li></ul> <p>A model result does not establish a universal grant level.</p> <hr> <h1>17. Consequential adoption and scaling</h1> <h2>17.1 Domestic or local enactment</h2> <p>A consequential shared-capital institution requires, as applicable:</p> <ul><li>valid legal form;</li> <li>lawful capitalization;</li> <li>budget authority;</li> <li>beneficiary rules;</li> <li>fiduciary duties;</li> <li>investment mandate;</li> <li>custody;</li> <li>audit;</li> <li>challenge;</li> <li>securities, pension, banking, tax, labour, procurement, competition, and property compliance;</li> <li>Indigenous and community interfaces;</li> <li>transition and closure.</li></ul> <h2>17.2 Cross-jurisdiction adoption</h2> <p>A compact shall additionally define:</p> <ul><li>participating authorities;</li> <li>contribution rights and duties;</li> <li>voting;</li> <li>asset ownership;</li> <li>custody;</li> <li>currency;</li> <li>dispute jurisdiction;</li> <li>withdrawal;</li> <li>non-member effects;</li> <li>insolvency;</li> <li>dissolution.</li></ul> <h2>17.3 Treaty-scale adoption</h2> <p>Nothing in this Protocol creates Treaty competence to hold global productive capital generally.</p> <p>A Treaty-scale shared-capital instrument would require:</p> <ul><li>an existing conferred competence or new protocol within valid Treaty authority;</li> <li>clear relationship to Article 18;</li> <li>Party authorization;</li> <li>non-member treatment;</li> <li>global and local distributional analysis;</li> <li>Indigenous and affected-community standing;</li> <li>separation from general Treaty regulatory power;</li> <li>review and withdrawal.</li></ul> <p>The GCF is not silently converted into this role.</p> <h2>17.4 GMEAIA lifecycle</h2> <p>The Protocol shall not create a local substitute for GMEAIA’s controlled lifecycle states.</p> <p>Each implementation supplies only its domain profile:</p> <ul><li>object;</li> <li>authority;</li> <li>capitalization;</li> <li>consequence profile;</li> <li>beneficiary effects;</li> <li>investment and distribution mandate;</li> <li>handoffs;</li> <li>unresolved duties;</li> <li>correction;</li> <li>closure.</li></ul> <p>GMEAIA controls the state grammar.</p> <hr> <h1>18. Governance and anti-capture safeguards</h1> <h2>18.1 Political capture</h2> <p>A shared-capital institution shall disclose and control:</p> <ul><li>appointment power;</li> <li>removal power;</li> <li>budget dependence;</li> <li>campaign or partisan conflicts where relevant;</li> <li>related-party investment;</li> <li>preferential access;</li> <li>lobbying by investees;</li> <li>revolving doors;</li> <li>manager political contributions where disclosure is lawful;</li> <li>use of the fund to reward allies or punish opponents.</li></ul> <h2>18.2 Manager capture</h2> <p>A nominally public fund may be functionally controlled by:</p> <ul><li>a small set of external asset managers;</li> <li>index providers;</li> <li>custodians;</li> <li>consultants;</li> <li>data vendors;</li> <li>rating agencies;</li> <li>technology platforms.</li></ul> <p>Observation Independence and common-mode dependency review shall apply proportionate to consequence.</p> <h2>18.3 Beneficiary capture</h2> <p>A fund shall consider whether:</p> <ul><li>older cohorts externalize risk to younger cohorts;</li> <li>current residents exhaust future reserves;</li> <li>organized beneficiaries dominate diffuse beneficiaries;</li> <li>high-balance accounts dominate governance;</li> <li>professional insiders control technical decisions without challenge;</li> <li>local incumbents block new entrants.</li></ul> <h2>18.4 Asset-owner capture of governance</h2> <p>A fund shall not acquire special public-law authority because it is economically important.</p> <p>Conversely, an enterprise shall not acquire governance authority over the fund merely because the fund depends on its returns.</p> <h2>18.5 Privatization and appropriation risk</h2> <p>Closure, fiscal crisis, political transition, or privatization shall not allow fund assets to be transferred to insiders or converted into general patronage without lawful process.</p> <p>The charter shall state:</p> <ul><li>who owns residual assets;</li> <li>whether beneficiaries have vested claims;</li> <li>what happens under insolvency;</li> <li>what cannot be appropriated through ordinary political discretion.</li></ul> <h2>18.6 Fund proliferation</h2> <p>Pluralism does not mean creating institutions without necessity.</p> <p>A new fund should state why:</p> <ul><li>an existing fund cannot perform the function;</li> <li>ordinary budgeting is insufficient;</li> <li>direct distribution is insufficient;</li> <li>a cooperative or private vehicle is insufficient;</li> <li>a simpler trust or account would not work.</li></ul> <p>Institution count is not a success metric.</p> <hr> <h1>19. Transparency, data, and valuation</h1> <h2>19.1 Institutional transparency</h2> <p>A consequential fund should publish:</p> <ul><li>charter;</li> <li>board and appointment;</li> <li>conflicts;</li> <li>audited accounts;</li> <li>asset classes;</li> <li>material holdings subject to lawful confidentiality;</li> <li>managers;</li> <li>fees;</li> <li>voting policy;</li> <li>distributions;</li> <li>valuation method;</li> <li>leverage;</li> <li>risk;</li> <li>benchmark;</li> <li>significant related-party transactions;</li> <li>outcome evaluation.</li></ul> <p>Transparency duties apply more strongly to the institution than to individual beneficiaries.</p> <h2>19.2 Beneficiary privacy</h2> <p>Individual accounts, distributions, disability accommodations, debt status, and other personal information shall be purpose-limited.</p> <p>Public beneficial ownership requirements, where lawful, do not justify publishing every beneficiary’s personal financial history.</p> <h2>19.3 Valuation</h2> <p>The fund shall distinguish:</p> <ul><li>market value;</li> <li>model value;</li> <li>book value;</li> <li>illiquid valuation;</li> <li>public-service value;</li> <li>ecological condition;</li> <li>cultural or reparative significance.</li></ul> <p>A non-market public objective does not make an investment financially valuable by definition.</p> <h2>19.4 Unlisted assets</h2> <p>Private companies, infrastructure, land, IP, and other illiquid assets require:</p> <ul><li>independent valuation methods;</li> <li>conflict disclosure;</li> <li>review cadence;</li> <li>uncertainty;</li> <li>transaction comparators where available;</li> <li>impairment rules.</li></ul> <p>A manager shall not hide losses by delaying valuation.</p> <h2>19.5 Recognition-record firewall</h2> <p>Investment and beneficiary systems shall conform to CIS/0.2.4.</p> <p>Where a social-inheritance distribution or dividend creates a financial asset, the financial system shall create the necessary financial record directly. It shall not require reconstruction from care, civic, cultural, ecological, or relational records.</p> <hr> <h1>20. Distributional and macroeconomic review</h1> <p>A shared-capital mechanism shall evaluate more than portfolio return.</p> <h2>20.1 Distribution</h2> <p>Review should examine:</p> <ul><li>wealth distribution;</li> <li>capital-income distribution;</li> <li>age;</li> <li>gender where lawful and relevant;</li> <li>disability;</li> <li>geography;</li> <li>income;</li> <li>existing asset ownership;</li> <li>renters and owners;</li> <li>workers and non-workers;</li> <li>migrants and mobile populations where relevant;</li> <li>communities affected by the underlying assets.</li></ul> <h2>20.2 Asset-price effects</h2> <p>A capital grant can raise prices where supply is constrained.</p> <p>Evaluation shall consider whether social inheritance or fund investment inflates:</p> <ul><li>housing;</li> <li>land;</li> <li>education;</li> <li>business acquisition;</li> <li>local securities;</li> <li>other scarce assets.</li></ul> <p>Where the mechanism mainly capitalizes scarcity into higher prices, redesign may be required.</p> <h2>20.3 Crowding and additionality</h2> <p>Public/shared investment should evaluate:</p> <ul><li>whether private capital would have financed the activity anyway;</li> <li>whether public capital crowds in or crowds out alternatives;</li> <li>whether public risk is appropriately compensated;</li> <li>whether the investment changes ownership distribution;</li> <li>whether mission conditions reduce or improve effectiveness.</li></ul> <h2>20.4 Fiscal interaction</h2> <p>A fund shall disclose:</p> <ul><li>required public contributions;</li> <li>foregone current spending;</li> <li>contingent liabilities;</li> <li>guarantees;</li> <li>dividend assumptions;</li> <li>tax treatment;</li> <li>budget dependence;</li> <li>effect on public debt where applicable.</li></ul> <p>Moving expenditure off-budget into a fund does not make the fiscal cost disappear.</p> <h2>20.5 AUBI and services</h2> <p>Evaluation shall test whether shared-capital funding is being used politically to justify:</p> <ul><li>reducing AUBI;</li> <li>privatizing universal basic services;</li> <li>replacing disability support;</li> <li>replacing pensions without equivalent rights;</li> <li>shifting public obligations into volatile asset returns.</li></ul> <p>Those are separate policy decisions.</p> <h2>20.6 First-receiver incidence</h2> <p>Section 20.2 evaluates whether a mechanism capitalizes scarcity into higher prices. This section addresses the sequence that produces that result: who receives deployed capital, dividends, or social-inheritance value before those prices adjust.</p> <p>For each material deployment, distribution, or disbursement class, the institution shall record a First-Receiver Incidence Statement to the standard in Financial Systems §6.6, adapted to capital rather than currency, identifying at minimum:</p> <ul><li>the classes receiving value first, and those receiving it only through subsequent exchange;</li> <li>constrained-supply channels through which first recipients are expected to spend or invest, connecting this record to the §20.2 review;</li> <li>whether any first-recipient class also participates in the allocation decision, engaging §18.3 and §18.4;</li> <li>cohort effects where a social-inheritance mechanism releases value to successive age cohorts under changing market conditions, engaging §3.11 and §24.11.</li></ul> <p>Where a distribution is universal or uniform across beneficiaries, the institution may record that the first-receiver set is coextensive with the beneficiary population, subject to review of heterogeneous real effects through access, geography, existing asset ownership, and local price response.</p> <p>The record is a distributional disclosure. It does not create a means test, a beneficiary eligibility condition, a restriction on use under §11.7, or a finding of fiduciary breach. Under §3.10, it may support review and may not by itself redirect a portfolio.</p> <hr> <h1>21. Stress testing and failure modes</h1> <p>At minimum, significant shared-capital institutions should stress test:</p> <ol><li>severe market drawdown;</li> <li>prolonged low returns;</li> <li>inflation shock;</li> <li>liquidity shock;</li> <li>currency mismatch;</li> <li>concentrated manager failure;</li> <li>custodian or platform failure;</li> <li>cyber incident;</li> <li>private-asset valuation failure;</li> <li>political pressure to invest or divest;</li> <li>related-party corruption;</li> <li>beneficiary-run or premature distribution pressure;</li> <li>intergenerational raid on reserves;</li> <li>excessive leverage;</li> <li>index or model common-mode failure;</li> <li>local-development portfolio concentration;</li> <li>sudden withdrawal by a participating jurisdiction;</li> <li>Treaty or compact failure;</li> <li>social-inheritance fraud or identity error;</li> <li>predatory capture of individualized grants;</li> <li>asset-price inflation caused by the programme;</li> <li>public-equity conflict with regulator independence;</li> <li>Indigenous or community refusal;</li> <li>stewardship-transition failure;</li> <li>fund insolvency;</li> <li>dissolution with unresolved claims;</li> <li>politically motivated denial of beneficiary status;</li> <li>recognition-data contamination;</li> <li>mission drift toward asset maximization;</li> <li>capture by professional fund managers.</li></ol> <p>Stress tests shall include protected continuity and recovery, not only financial loss.</p> <hr> <h1>22. Rights, challenge, and remedy</h1> <h2>22.1 Beneficiary challenge</h2> <p>A person materially affected by:</p> <ul><li>eligibility;</li> <li>account attribution;</li> <li>distribution;</li> <li>factual record;</li> <li>unlawful discrimination;</li> <li>asset custody;</li> <li>fees;</li> <li>unauthorized disclosure;</li> <li>vested claim treatment</li></ul> <p>shall have an accessible challenge route.</p> <h2>22.2 Investment-policy challenge</h2> <p>Beneficiaries or affected parties may challenge:</p> <ul><li>conflict of interest;</li> <li>ultra vires investment;</li> <li>unlawful discrimination;</li> <li>breach of fiduciary mandate;</li> <li>protected-domain violation;</li> <li>false reporting;</li> <li>unauthorized related-party transaction.</li></ul> <p>Disagreement with an investment does not automatically establish a right to overturn it.</p> <h2>22.3 Wrongful action</h2> <p>A framework-compliant remedy may include:</p> <ul><li>record correction;</li> <li>payment correction;</li> <li>account restoration;</li> <li>fee refund;</li> <li>reversal where feasible;</li> <li>compensation;</li> <li>manager removal through lawful process;</li> <li>independent investigation;</li> <li>charter amendment;</li> <li>referral to regulator or court.</li></ul> <h2>22.4 Essential continuity</h2> <p>Dispute, insolvency, closure, or political transition shall protect, where applicable:</p> <ul><li>vested beneficiary claims;</li> <li>pensions;</li> <li>essential-service funding;</li> <li>worker rights;</li> <li>personal records;</li> <li>access to appeal;</li> <li>Indigenous and community data;</li> <li>unresolved legal claims.</li></ul> <hr> <h1>23. Required domain records</h1> <p>The Protocol relies on CIS and GMEAIA for shared constitutional and lifecycle records. The following are domain-specific records or profiles that may be implemented as separate forms or as fields inside existing records according to consequence and proportionality.</p> <ol><li><strong>SCSI-01 Constituting and Authority Record</strong> — legal form, mandate, authority, jurisdiction, consequence profile.</li> <li><strong>SCSI-02 Beneficiary Constitution Record</strong> — beneficiary class, standing, participation, exclusions, purpose-limited identification/attestation where needed, challenge.</li> <li><strong>SCSI-03 Capitalization Provenance Record</strong> — asset source, authority, restrictions, liabilities, valuation.</li> <li><strong>SCSI-04 Public Risk and Return Record</strong> — public support, risk borne, return instrument, alternatives.</li> <li><strong>SCSI-05 Investment Mandate Record</strong> — objectives, risk, liquidity, diversification, exclusions, strategic scope.</li> <li><strong>SCSI-06 Custody and Manager Independence Record</strong> — custodian, managers, conflicts, common-mode dependencies.</li> <li><strong>SCSI-07 Ownership and Voting Rights Record</strong> — title, voting, board, control, stewardship policy.</li> <li><strong>SCSI-08 Concentration and Control Review</strong> — issuer, sector, manager, geographic, voting and public-power concentration.</li> <li><strong>SCSI-09 Distribution and Reserve Record</strong> — dividend, reinvestment, reserves, losses, amendment.</li> <li><strong>SCSI-10 Social Inheritance Design Record</strong> — eligibility, vesting, access, restrictions, creditor, tax and AUBI interface.</li> <li><strong>SCSI-11 Individual Capital Claim Record</strong> — legal owner/claimant under the constituting instrument, custody, access, transfer, purpose-limited continuity reference where needed, correction, external-status handling, closure.</li> <li><strong>SCSI-12 Worker and Community Ownership Interface</strong> — worker rights, community standing, conversion pathway, downside concentration.</li> <li><strong>SCSI-13 Indigenous and Protected-Asset Interface</strong> — affected authority, consent, non-transfer, excluded assets.</li> <li><strong>SCSI-14 Cross-Jurisdiction Compact Record</strong> — parties, contributions, ownership, voting, exit, insolvency.</li> <li><strong>SCSI-15 Data and Recognition-Record Boundary Record</strong> — purpose, classes, financial record creation, prohibited secondary use.</li> <li><strong>SCSI-16 Valuation and Illiquidity Record</strong> — methodology, uncertainty, conflicts, review.</li> <li><strong>SCSI-17 Stress-Test and Continuity Record</strong> — scenarios, protected minimums, recovery.</li> <li><strong>SCSI-18 Outcome and Distributional Evaluation</strong> — financial and independent material outcomes.</li> <li><strong>SCSI-19 Wrongful Action and Remedy Record</strong> — error, affected claims, restoration, compensation.</li> <li><strong>SCSI-20 Succession, Devolution, and Dissolution Plan</strong> — destination of assets, claims, records, authority return, and referral of person-level succession questions to their competent external owner.</li></ol> <p>Where a canonical record from CIS, GMEAIA, Hearthstone, Financial Systems, Justice, or another specialized interface already satisfies the requirement, it should be imported rather than duplicated.</p> <hr> <h1>24. Falsification and non-scaling gates</h1> <p>A conforming record is not evidence that the mechanism should scale.</p> <p>The following findings should trigger narrowing, redesign, suspension, or non-scaling.</p> <h2>24.1 Ownership-broadening failure</h2> <p>The mechanism fails its central purpose if, after reasonable evaluation:</p> <ul><li>intended beneficiaries acquire no meaningful capital claim, return, or governance benefit;</li> <li>administrative intermediaries capture most of the value;</li> <li>the fund merely changes the nominal owner while leaving effective control equally concentrated;</li> <li>broadening ownership is too small to matter relative to cost.</li></ul> <h2>24.2 Public-concentration failure</h2> <p>Narrow or redesign if plural shared-capital institutions converge into:</p> <ul><li>one dominant fund;</li> <li>one manager;</li> <li>one platform;</li> <li>one political appointment chain;</li> <li>one voting bloc</li></ul> <p>with insufficient challenge or exit.</p> <h2>24.3 Social-inheritance price-capitalization failure</h2> <p>Narrow or redesign if grants mainly increase prices of constrained assets and leave recipients no better able to own productive or durable wealth.</p> <h2>24.4 Debt-capture failure</h2> <p>Narrow or redesign if social-inheritance assets are systematically captured by:</p> <ul><li>predatory lenders;</li> <li>excessive fees;</li> <li>fraud;</li> <li>coercive family or institutional claims</li></ul> <p>before they create durable beneficiary wealth.</p> <h2>24.5 AUBI substitution failure</h2> <p>The architecture fails constitutional purpose if capital distributions become a rationale for weakening unconditional material security.</p> <h2>24.6 Political allocation failure</h2> <p>Suspend or redesign if investment becomes persistently driven by:</p> <ul><li>partisan loyalty;</li> <li>patronage;</li> <li>donor influence;</li> <li>retaliation;</li> <li>opaque ministerial direction</li></ul> <p>rather than the enacted mandate.</p> <h2>24.7 Public-risk/shared-upside failure</h2> <p>Narrow the use of public equity, royalties, or similar instruments if they consistently:</p> <ul><li>add administrative and governance burden;</li> <li>deter beneficial activity;</li> <li>produce little public return relative to risk and public purpose;</li> <li>generate losses outside the authorized or disclosed loss tolerance;</li> <li>create conflicts with regulation;</li> <li>depend on selective reporting of successful holdings while omitting write-offs, failed investments, guarantees, fees, subsidies, or opportunity costs;</li> <li>perform worse at portfolio or programme level than simpler grants, procurement conditions, loans, open-access arrangements, or other relevant comparators.</li></ul> <p>A mechanism does not pass this gate because one prominent investment succeeds. Evaluation shall use the portfolio, cohort, or programme unit defined ex ante in the authorization.</p> <h2>24.8 Manager-capture failure</h2> <p>Redesign if external managers, consultants, custodians, or index providers become de facto controllers of public capital without corresponding accountability.</p> <h2>24.9 Indigenous or protected-domain failure</h2> <p>A mechanism shall not scale where it:</p> <ul><li>treats Indigenous assets as generic public capital;</li> <li>bypasses affected-nation authority;</li> <li>converts rematriation into portfolio acquisition;</li> <li>monetizes protected knowledge without authority.</li></ul> <h2>24.10 Recognition-data failure</h2> <p>A mechanism shall not scale where care, ecological, civic, cultural, or relational records become de facto beneficiary, credit, investment, fraud, or reputation scores.</p> <h2>24.11 Intergenerational failure</h2> <p>Redesign if:</p> <ul><li>current beneficiaries systematically raid long-term capital;</li> <li>future-generation rhetoric blocks justified present use;</li> <li>reserve rules become politically untouchable despite changed conditions.</li></ul> <h2>24.12 Complexity failure</h2> <p>Do not create or preserve a separate fund where ordinary budgeting, a simple trust, direct distribution, cooperative ownership, or another simpler instrument achieves the objective with lower constitutional and administrative burden.</p> <hr> <h1>25. Framework interfaces</h1> <h2>25.1 Constitutional Interface Specification</h2> <p>CIS/0.2.4 controls:</p> <ul><li>authority boundaries;</li> <li>decision-chain separation;</li> <li>protected non-transfer;</li> <li>Recognition-Record Purpose Firewall;</li> <li>person-continuity and purpose-limited attestation;</li> <li>non-transitive cross-domain linkage;</li> <li>external-status ingestion and surviving-duty continuity;</li> <li>automatic controls;</li> <li>conformance;</li> <li>challenge and continuity.</li></ul> <p>Shared ownership does not create jurisdiction.</p> <h2>25.2 GMEAIA</h2> <p>GMEAIA controls:</p> <ul><li>authority-effect labels;</li> <li>consequence profiles;</li> <li>response states;</li> <li>clocks;</li> <li>handoffs;</li> <li>correction;</li> <li>unresolved-duty custody;</li> <li>closure.</li></ul> <p>This Protocol supplies domain content only.</p> <h2>25.3 Adaptive Tax</h2> <p>Adaptive Tax owns:</p> <ul><li>compulsory revenue collection;</li> <li>tax bases;</li> <li>inheritance and gift taxation;</li> <li>fiscal credits;</li> <li>apportionment;</li> <li>fiscal administration;</li> <li>lawful revenue transfer into shared-capital institutions.</li></ul> <p>This Protocol owns:</p> <ul><li>capital custody after transfer;</li> <li>investment;</li> <li>ownership rights;</li> <li>beneficiaries;</li> <li>distributions;</li> <li>social inheritance.</li></ul> <h2>25.4 AUBI</h2> <p>AUBI owns unconditional material security.</p> <p>This Protocol shall not condition AUBI on capital participation or contribution, and social inheritance shall not become a substitute for Layer 1.</p> <h2>25.5 Financial Systems</h2> <p>Financial Systems owns:</p> <ul><li>Hearts and Leaves operations;</li> <li>Treasury;</li> <li>reserve and liquidity architecture;</li> <li>settlement;</li> <li>ICTL;</li> <li>financial observability.</li></ul> <p>Where a shared-capital instrument uses Hearts or other GGF financial rails, Financial Systems governs the rail and this Protocol governs the ownership mandate.</p> <h2>25.6 Nested Economies</h2> <p>Nested Economies governs:</p> <ul><li>economic subsidiarity;</li> <li>cross-scale compacts;</li> <li>material exit;</li> <li>protected non-convertibility;</li> <li>jointly constituted economic authority.</li></ul> <p>This Protocol governs the fund or account formed through those arrangements.</p> <h2>25.7 Work in Liberation</h2> <p>Work in Liberation governs worker rights and labour governance.</p> <p>This Protocol may finance worker ownership but does not define worker worth, contribution value, or labour standards.</p> <h2>25.8 Hearthstone</h2> <p>Hearthstone governs:</p> <ul><li>voluntary commons conversion;</li> <li>steward-ownership conversion;</li> <li>rematriation;</li> <li>stewardship trusts;</li> <li>separately lawful asset transition.</li></ul> <p>This Protocol can provide capital to a transition but cannot compel the transition.</p> <p>The interface also runs in the other direction. Hearthstone explicitly applies to transitions involving shared capital, endowments, funds, and debt arrangements. Where a shared-capital institution is itself being donated, sold, converted, reconstituted as a stewardship trust, rematriated, subjected to a lawful public-interest acquisition, or otherwise transitioned, <strong>Hearthstone governs the transition pathway, claims, title or trust constitution, conveyance, and succession process</strong>. This Protocol continues to govern the institution’s beneficiaries, accrued claims, custody and investment obligations, continuity, valuation, distribution, and unresolved duties before, during, and after that transition.</p> <p>Neither framework may use the other’s purpose to bypass claimant, pension, creditor, worker, Indigenous, beneficiary, tax, or adjudicative protections.</p> <h2>25.9 Pathfinder / Regenerative Enterprise</h2> <p>Pathfinder and enterprise frameworks own enterprise-level transition practices such as ESOPs, Community Investment Trusts, profit sharing, and steward ownership.</p> <p>This Protocol supplies fund architecture where public or collective capital co-invests in or diversifies those claims.</p> <h2>25.10 Bioregional Polis</h2> <p>Bioregional Polis owns municipal land and Community Land Trust mechanisms.</p> <p>This Protocol may govern pooled financial capital used by a local purchase or investment fund, without assuming control of land law or CLT governance.</p> <h2>25.11 Treaty and Global Commons Fund</h2> <p>The Treaty owns conferred public-finance authority and the GCF.</p> <p>The GCF is not a general social wealth fund. A future Treaty protocol may create a shared-capital or social-inheritance function only through valid competence and explicit adoption.</p> <h2>25.12 Meta-Governance</h2> <p>Meta-Governance may coordinate shared-capital interfaces among valid authorities.</p> <p>It does not become a global investment ministry.</p> <h2>25.13 Justice and data governance</h2> <p>Justice frameworks govern:</p> <ul><li>adjudication;</li> <li>fiduciary breach;</li> <li>rights;</li> <li>remedy;</li> <li>lawful enforcement.</li></ul> <p>Aurora Accord v1.3.2 and other competent data-governance instruments govern:</p> <ul><li>privacy;</li> <li>identity-function separation;</li> <li>anti-linkage and minimum disclosure;</li> <li>cybersecurity;</li> <li>algorithmic use;</li> <li>retention;</li> <li>protected data.</li></ul> <p>Neither gains investment or ownership authority merely by performing those functions.</p> <h2>25.14 Sundown Protocol</h2> <p>Sundown may identify sectors, firms, or transition conditions and may propose coordinated investment responses.</p> <p>This Protocol governs whether a public, pension, sovereign, community, or other shared-capital institution actually possesses authority to:</p> <ul><li>exclude new investment;</li> <li>divest;</li> <li>coordinate a common timetable;</li> <li>alter portfolio strategy;</li> <li>restructure a sovereign or public fund.</li></ul> <p>A Sundown compliance indicator, transition designation, or escalation level does not itself amend a fund mandate. Divestment coordination is valid only where the participating fund or competent authority has adopted the relevant rule or entered a valid compact.</p> <h2>25.15 Water & Sanitation and other domain trust funds</h2> <p>Domain frameworks may constitute purpose-specific public or community funds under their own valid authority.</p> <p>Water & Sanitation <code>WAT-16</code> is a conformance precedent for legal custodian, public purpose, eligible uses, segregation, procurement, beneficial-ownership disclosure, audit, conflicts, reserves, insolvency, restitution, and dissolution.</p> <p>This Protocol supplies the general shared-capital architecture where useful; it does not displace stronger domain-specific controls or convert a service trust into a general investment fund.</p> <h2>25.16 Aegis Protocol</h2> <p>Aegis governs voluntary and lawfully constituted security-capability transition and civilian conversion. Its finance model expressly rejects a self-created global trust and instead permits participants to create or join separately constituted transition funds, development banks, public trusts, grant facilities, pension-backed vehicles, and project-finance arrangements.</p> <p>This Protocol governs any such vehicle to the extent it is a shared-capital institution, including:</p> <ul><li>charter and custody;</li> <li>investment and risk mandate;</li> <li>beneficiary and claimant protections;</li> <li>public-purpose and prohibited-use boundaries;</li> <li>loss allocation and portfolio accounting;</li> <li>pension interfaces;</li> <li>audit, challenge, insolvency, succession, and dissolution.</li></ul> <p>Aegis governs the civilian capability-transition purpose and mission exclusions. It does not obtain authority over pension assets, public capital, or investment mandates merely because the financing supports an Aegis transition.</p> <hr> <h1>26. Legacy-content migration</h1> <p>This Protocol is intended to reduce duplication rather than absorb every ownership-related proposal in the corpus.</p> <h2>26.1 Pathfinder</h2> <p>Preserve Pathfinder’s enterprise-level:</p> <ul><li>ESOPs;</li> <li>Community Investment Trusts;</li> <li>profit sharing;</li> <li>steward ownership;</li> <li>patient-capital practice.</li></ul> <p>Migrate only cross-enterprise fund architecture that requires a general public/shared-capital owner.</p> <h2>26.2 Bioregional Polis</h2> <p>Preserve:</p> <ul><li>Community Land Trusts;</li> <li>rights of first refusal;</li> <li>local purchase mechanisms;</li> <li>municipal land policy.</li></ul> <p>A Community Purchase Fund should interface with this Protocol only to the extent it becomes a pooled financial-capital institution.</p> <p>Fixed amounts, percentages, tax rates, or automatic funding multipliers in the existing Polis text remain subject to their own constitutional and Adaptive Tax review; they are not imported into this Protocol.</p> <h2>26.3 Hearthstone</h2> <p>Preserve Hearthstone’s voluntary and separately lawful:</p> <ul><li>cooperative conversion;</li> <li>stewardship trusts;</li> <li>bequests;</li> <li>public-interest purchase;</li> <li>commons dividends inside stewardship entities.</li></ul> <p>Do not move stewardship title or rematriation into this Protocol.</p> <p>Where a shared-capital institution, endowment, fund, or debt arrangement is itself the object of a Hearthstone transition, preserve the opposite allocation as well: Hearthstone owns the transition pathway and conveyance/claims architecture; this Protocol owns the beneficiary, fiduciary, investment, custody, distribution, pension, and continuity consequences of the institution being transitioned.</p> <h2>26.4 Treaty</h2> <p>Preserve:</p> <ul><li>GCF as a global public-goods fund;</li> <li>Article 18.6 commons-dividend authority route.</li></ul> <p>Do not silently reinterpret either as general planetary capital ownership.</p> <h2>26.5 AUBI</h2> <p>AUBI references commons dividends and fiscal funding.</p> <p>Social inheritance shall be added only as a separate capital interface if AUBI later needs to explain how material security differs from capital endowment.</p> <p>AUBI eligibility remains independent.</p> <h2>26.6 Adaptive Tax</h2> <p>Adaptive Tax v0.1.2 already routes:</p> <ul><li>fiscal transfers;</li> <li>inheritance taxation;</li> <li>revenue earmarks</li></ul> <p>to this Protocol where a shared-capital institution receives the proceeds.</p> <p>No tax instrument migrates here.</p> <h2>26.7 Legacy “Planetary Hedge Fund” and similar proposals</h2> <p>Any legacy proposal using a hedge fund, sovereign investment vehicle, public venture fund, or regenerative investment pool shall be classified before migration.</p> <p>Possible dispositions are:</p> <ul><li>financial-risk mechanism under Financial Systems;</li> <li>public/shared-capital fund under this Protocol;</li> <li>insurance mechanism;</li> <li>ordinary budget programme;</li> <li>retirement of the proposal.</li></ul> <p>Naming an object a “fund” does not establish its constitutional home.</p> <h2>26.8 Sundown Protocol</h2> <p>Sundown v2.1 currently states that Pathfinder pension funds, sovereign wealth funds, and public investment vehicles commit to divest from non-compliant corporations, and its escalation ladder reaches an Investment Freeze in which public funds divest and new investment is prohibited.</p> <p>Migration shall distinguish two valid pathways:</p> <ul><li><strong>mandate pathway:</strong> the fund’s existing or lawfully amended charter contains the relevant exclusion, stewardship, or transition rule;</li> <li><strong>compact pathway:</strong> the fund or its competent authority voluntarily joins a bounded divestment coordination compact specifying scope, evidence, timing, beneficiary effects, review, exit, and re-entry.</li></ul> <p>The Sundown framework itself shall not be treated as the investment authority. Its indicator or transition designation may supply an input where the fund’s own mandate validly gives that input consequence.</p> <p>Sundown’s sovereign-wealth restructuring material should be reframed as advisory portfolio-transition support unless a fund’s competent authority adopts it.</p> <h2>26.9 Regenerative Journeys — BAZ Intergenerational Trust Fund</h2> <p>Regenerative Journeys v1.1 already proposes a <strong>BAZ Intergenerational Trust Fund</strong> receiving a mandatory ten percent of tourism-levy revenue for 50+ year restoration or cultural-preservation purposes with Youth Council co-approval.</p> <p>Disposition:</p> <ul><li>the trust-fund architecture is a live example of Sections 4.6 and 4.9;</li> <li>the tourism levy and mandatory ten-percent capitalization rule remain fiscal/domain-policy proposals requiring Adaptive Tax and competent fiscal authority;</li> <li>youth co-approval is a domain governance proposal, not a universal intergenerational-fund rule;</li> <li>the fund should import the charter, custody, loss, audit, beneficiary, challenge, and closure requirements of this Protocol at its next substantive revision.</li></ul> <h2>26.10 Religious & Spiritual Dialogue — Public Endowment</h2> <p>Religious & Spiritual Dialogue v1.8 proposes a permanent public endowment capitalized through the Global Commons Fund to generate sustainable operating revenue. It also identifies <em>waqf</em> as a long-horizon coordination precedent.</p> <p>Disposition:</p> <ul><li>the endowment is a Section 4.9 institution and should receive explicit charter, custody, investment, drawdown, conflict, audit, and dissolution rules;</li> <li>GCF capitalization is not automatic and requires the GCF’s own valid funding authority;</li> <li><em>waqf</em> and other religious or customary endowment traditions may inform design but remain governed by their own legal, religious, and community authority;</li> <li>no GGF framework should appropriate a tradition-specific institution as generic public property architecture.</li></ul> <h2>26.11 Millennium Protocol — time-indexed reparations trust</h2> <p>Millennium Protocol v1.0 proposes time-indexed reparations through “quantum-linked trust funds” managed by the Global Commons Fund.</p> <p>Disposition:</p> <ul><li>retain the reparative and deep-time design question as visionary research;</li> <li>do not treat “quantum-linked” custody, future-victim representation, GCF management, or time-indexed entitlement as currently operational financial architecture;</li> <li>any future implementation must separately constitute reparations authority, beneficiaries or future-interest representation, custody, investment mandate, time horizon, correction, and dissolution under the then-current constitutional stack.</li></ul> <p>Until that occurs, the proposal is not a live Shared Capital mechanism.</p> <h2>26.12 Water & Sanitation — Community Water Trust Fund</h2> <p>Water & Sanitation v5.2.2 already provides a strong domain-specific charter in <code>WAT-16</code> and associated finance records.</p> <p>Disposition:</p> <ul><li>preserve Water’s domain ownership of the Community Water Trust Fund;</li> <li>use <code>WAT-16</code> as a conformance precedent for future community and commons funds;</li> <li>do not duplicate or weaken its legal-custodian, segregation, procurement, beneficial-ownership, audit, reserve, insolvency, restitution, and dissolution controls;</li> <li>apply this Protocol only where pooled investment, intergenerational capital, beneficiary claims, or cross-domain shared-capital questions exceed Water’s domain-specific mandate.</li></ul> <h2>26.13 Aegis Protocol — transition-finance facilities and pension-backed vehicles</h2> <p>Aegis v1.3.4 Section 15 already contains two useful doctrines: it rejects a single framework-created global security/exploration trust, and it requires separately constituted transition-finance facilities with explicit contributors, beneficiaries, custody, investment mandate, exclusions, allocations, risk/loss, audit, withdrawal, insolvency, and dissolution. Preserve both as conformance precedents.</p> <p>Its reference to <strong>pension-backed vehicles</strong> requires an explicit boundary rather than deletion. Disposition:</p> <ul><li>preserve ordinary pension-fund investment in transition assets where the investment is independently permissible under pension law and the fund’s fiduciary mandate;</li> <li>preserve separately constituted project-finance or development vehicles in which pension institutions participate on lawful investment terms;</li> <li>do not interpret the Aegis transition objective as authority to redirect, pledge, subordinate, or impair accrued pension claims;</li> <li>require the Section 11.12 pension-backed-vehicle record whenever pension capital is materially exposed;</li> <li>where the transition objective cannot satisfy pension fiduciary, risk, liquidity, beneficiary, and loss-allocation requirements, use non-pension public finance instead.</li></ul> <p>This is a financing interface, not an Aegis investment mandate.</p> <hr> <h1>27. Open design questions</h1> <ol><li>Should the GGF recommend any default balance between collective social wealth funds and individualized social-inheritance accounts?</li> <li>Should social inheritance be universal, residence-based, citizenship-based, or governed by different rules at different scales?</li> <li>What vesting age or lifecycle trigger best balances autonomy, opportunity, and administrative simplicity?</li> <li>Should the baseline social-inheritance claim be unrestricted, use-limited, time-vested, or hybrid?</li> <li>How should disability and supported decision-making interact with individualized capital claims?</li> <li>What creditor and insolvency protections, if any, should social-inheritance assets receive?</li> <li>How should migration between jurisdictions affect portable capital claims?</li> <li>Should recipients retain claims after permanent emigration?</li> <li>How should a fund balance current dividends against reinvestment and future-generation reserves?</li> <li>When should public R&D or guarantees receive equity, royalties, open licensing, or no financial return?</li> <li>How should public funds exercise shareholder voting without becoming covert regulators?</li> <li>What concentration thresholds should trigger control review?</li> <li>How should several public/shared funds coordinate where their combined stake becomes controlling?</li> <li>When does a local-development mandate justify lower diversification?</li> <li>How should public funds avoid subsidizing politically favoured incumbents?</li> <li>Should beneficiary representatives hold formal board seats, electoral rights, advisory standing, or another role?</li> <li>Which fund information may remain temporarily confidential without undermining public accountability?</li> <li>How should private-company valuation be handled for social wealth funds?</li> <li>Should social inheritance be financed from ordinary revenue, inheritance taxation, commons revenue, public-asset returns, or a mixed portfolio?</li> <li>Should earmarking be constitutionalized or left to ordinary appropriations?</li> <li>Which pension-fund functions should conform to this Protocol when the pooled institution is publicly or collectively governed, while leaving accrued pension entitlements under pension law?</li> <li>How should collective capital claims interact with reparations without substituting one for the other?</li> <li>Which Indigenous-controlled fund interfaces can be specified generically without intruding on Indigenous law?</li> <li>How should social inheritance avoid inflating housing or education prices in supply-constrained systems?</li> <li>What evidence would justify concluding that broad social inheritance performs worse than simply increasing AUBI, universal services, or direct public investment?</li> <li>What evidence would justify abandoning public equity or shared-upside instruments in favour of simpler fiscal tools?</li> <li>How should fund closure distribute residual assets where beneficiaries have collective rather than individualized claims?</li> <li>Should the GGF distinguish “social wealth fund,” “public wealth fund,” “community wealth fund,” and “commons fund” as controlled terms?</li> <li>What tests should distinguish a permissible supplementary public-purpose mandate for pension assets from an impermissible repurposing of deferred beneficiary capital?</li> <li>What minimum empirical evidence should be required before scaling a real-money social-inheritance pilot?</li> <li>What evidence, governance route, and beneficiary protections are required before a shared-capital fund joins a coordinated divestment or exclusion compact such as Sundown?</li> <li>What portfolio-level loss metrics and reporting period best prevent public-risk/shared-upside programmes from being evaluated through cherry-picked winners?</li> <li>When, if ever, should a pension-backed transition vehicle be allowed to use guarantees, collateral, or risk structures beyond ordinary portfolio investment without exposing accrued beneficiary claims to public-policy objectives they did not authorize?</li></ol> <hr> <h1>28. Minimal viable protocol</h1> <p>A jurisdiction implementing only the minimum viable version should do five things.</p> <ol><li><strong>Map existing shared capital and lifecycle claims.</strong> Identify public, pension, community, worker, Indigenous-controlled where invited, and public-equity assets, while recording accrued pension claims separately from discretionary public capital, before creating a new fund.</li> <li><strong>Separate authority.</strong> Keep taxation, capitalization, custody, investment, distribution, audit, and adjudication distinguishable.</li> <li><strong>Create one bounded charter.</strong> State beneficiaries, mandate, capitalization, investment rights, distributions, conflicts, challenge, and closure.</li> <li><strong>Protect the floor.</strong> Do not use capital ownership to condition or replace AUBI Layer 1 or essential rights.</li> <li><strong>Test whether ownership actually broadened.</strong> Measure beneficiary capital claims, returns, control, fees, asset-price effects, capture, and distribution—not merely fund size.</li></ol> <p>If an implementation cannot identify who owns the assets, whom the fund serves, who can challenge it, how public and private authority remain separated, and what happens when the institution fails or closes, it is not ready for consequential deployment.</p> <hr> <h1>29. Closing doctrine</h1> <p>Economic security and economic ownership answer different questions.</p> <p>A society may ensure that nobody falls below a material floor while leaving most productive capital in a narrow set of hands. It may also create a large public fund while leaving ordinary people with no meaningful claim, voice, dividend, or exit. Neither nominal redistribution nor nominal public ownership is sufficient.</p> <p>The objective of this Protocol is therefore not to maximize state ownership, fund size, or the percentage of assets carrying a GGF label.</p> <p>It is to make it possible for many forms of shared capital to exist without collapsing into one owner; for public risk to receive a fair public return where appropriate; for workers and communities to acquire durable capital claims; and for each generation to inherit some economic agency from society as a whole rather than only from the family into which it was born.</p> <p>AUBI protects the ability to survive and refuse.</p> <p>Adaptive Tax defines lawful public contribution.</p> <p>Hearthstone enables voluntary and separately lawful changes in ownership form.</p> <p>Pathfinder and Bioregional Polis provide enterprise and place-based transition mechanisms.</p> <p>Shared Capital and Social Inheritance governs what happens when capital is deliberately held for broad beneficiaries across time.</p> <p>The constitutional settlement is:</p> <blockquote><p><strong>Guarantee material security without making dignity depend on ownership. Broaden capital ownership without making one public institution the universal owner. Retain public upside where public risk justifies it, without turning every subsidy into a title claim. Give future generations a claim without using them to silence present needs. Protect Indigenous and community property from compulsory commoning. And make every shared-capital institution capable of being challenged, divided, devolved, or closed.</strong></p></blockquote> <p>The final test is not how much capital the system accumulates.</p> <p>It is whether people and communities acquire durable economic agency <strong>without creating a new concentration of unchallengeable ownership power</strong>.</p>",1);function c(i){var e=o();n(1564),a(i,e)}export{c as default};
